// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Eğitim bilimleri ve öğrenme psikolojisi uygulamaları (üstbiliş, aralıklı tekrar, geri getirme pratiği, Vygotsky yakınsak gelişim, ölçme türleri) (zor).
const ozSocialscience17Zor = <(String, String, List<String>, String)>[
  ('Bjork ve Bjork\'ün Yeni Kullanmama Kuramı\'na göre bir bilgiyi tekrar çalışmak veya test etmek için "geri getirme gücünün biraz düşmesini beklemek" neden hemen tekrar yapmaktan daha fazla "depolama gücü" artışı sağlar?', 'Geri getirme gücü yüksekken yapılan tekrar zahmetsiz olduğu için yeni kodlama üretmez; erişim zorlaştığında başarılı geri getirme bellek izini yeniden yapılandırıp derinleştirir', ['Geri getirme gücü düştüğünde kısa süreli bellek tamamen boşaldığı için nöron sayısı iki katına çıkar', 'Bilgi hemen tekrar edildiğinde ileriye ket vurma mekanizması tüm önceki şemaları kalıcı olarak siler', 'Depolama gücü ile geri getirme gücü birbirine zıt çalıştığı için biri arttığında diğeri her zaman sıfırlanır'], 'Kurama göre depolama gücündeki kazanç, o anki geri getirme gücünün düşüklüğüyle doğru orantılıdır; hatırlamak için gereken bilişsel çaba arttıkça kalıcı depolama gücü daha çok artar.'),
  ('İki öğrenciden Ali bir makaleyi okurken bilgisayarda eşzamanlı mesajlaşma bildirimlerini açık tutmakta, Burak ise telefonu başka odaya bırakıp tek odakla okumaktadır; Ali "Ben aynı anda iki işi yapmaya alışkınım, sürem uzasa da aynı derecede öğreniyorum" iddiasındadır. Bilişsel bilim bulgularına göre Ali\'nin iddiası nasıl değerlendirilmelidir?', 'Yanlıştır; görev geçişleri dikkat kalıntısı yaratır ve öğrenmeyi hipokampus merkezli bildirimsel bellekten daha katı olan striatum temelli yüzeysel belleğe kaydırarak transferi bozar', ['Doğrudur; dijital çağda büyüyen bireylerde bölünmüş dikkat paralel işlemciler geliştirerek derin işlemeyi hızlandırır', 'Kısmen doğrudur; süre uzatıldığında bölünmüş dikkat altında öğrenilen bilgilerin kavramsal esnekliği tek odaklı çalışmadan daha yüksek olur', 'Yanlıştır; çünkü mesajlaşma yalnızca görsel belleği etkiler, sözel metinlerin anlaşılması üzerinde hiçbir olumsuz etkisi yoktur'], 'Foerde, Knowlton ve Poldrack\'ın araştırmaları, çoklu görev (multitasking) altında öğrenmenin esnek ve kavramsal (hipokampal) bellek yerine esnek olmayan alışkanlık belleğine dayanmasına yol açtığını göstermiştir.'),
  ('Cepeda ve arkadaşlarının "aralık etkisi" üzerine yaptığı geniş çaplı çalışmalara göre, sınav tarihi (tutma aralığı - retention interval) 30 gün sonra olan bir öğrenci ile 180 gün sonra olan bir öğrencinin ideal tekrar boşluğu (çalışma oturumları arasındaki süre) nasıl farklılaşmalıdır?', 'Sınav tarihi uzaklaştıkça çalışma oturumları arasındaki ideal boşluk da uzatılmalıdır; 180 gün sonraki sınav için tekrar aralığı 30 gün sonraki sınava göre daha geniş tutulmalıdır', ['Her iki sınav için de en ideal tekrar boşluğu sabit olarak tam yirmi dört saattir', 'Sınav tarihi ne kadar uzaksa tekrarlar ilk hafta içine o kadar sıkıştırılmalıdır', '180 gün sonraki sınav için hiç ara verilmeden tek blok çalışılmalı, 30 gün sonraki sınav için ayda bir çalışılmalıdır'], 'Araştırmalar, ideal tekrar aralığının hedef tutma süresinin (sınav tarihinin) yaklaşık %10-20\'si civarında ölçeklendiğini; daha uzun vadeli hedefler için daha geniş aralıkların gerektiğini ortaya koymuştur.'),
  ('Bir metnin okunması çok kolay bir yazı tipi yerine hafifçe okunması zor bir yazı tipiyle sunulduğunda veya metindeki bazı harfler silik bırakıldığında kavrama puanlarının bazen arttığını bulan çalışmalar, bu durumu üstbiliş açısından nasıl açıklar?', 'Akıcılığın azalması (disfluency) üstbilişsel bir uyarı sinyali üreterek "bunu kolayca anladım" rehavetini kırar ve analitik, derin işlemeyi devreye sokar', ['Zor okunan metinler göz kaslarını yorduğu için beynin görsel korteksini kapatıp doğrudan uzun süreli belleği açar', 'Kolay okunan yazı tipleri kısa süreli bellekteki sesbilimsel döngüyü tamamen kilitler', 'Silik harfler öğrencinin okuma hızını on kat artırdığı için çalışma süresini kısaltır'], 'Algısal akıcılıktaki hafif kesinti, otomatik ve yüzeysel okumayı durdurup üstbilişsel izlemeyi tetikleyerek bilişsel çabayı artırabilir.'),
  ('Bir öğretmen öğrencilerine "Konuyu tam öğrenmeden kesinlikle test çözmeyin; önce konuyu beş kez okuyup tamamen kusursuz hale getirin, sonra soru çözün" tavsiyesinde bulunmaktadır. Öğrenme bilimi ilkeleri ışığında bu tavsiye neden hatalıdır?', 'Test çözmeyi yalnızca ölçme aracı olarak görüp öğrenmeyi inşa eden bir geri getirme ve tanı koyma aracı olduğunu göz ardı ettiği ve tekrar okumayla akıcılık yanılsamasını beslediği için', ['Beş kez okumanın az olduğu, test çözmeye geçmeden önce en az on beş kez okuma yapılması gerektiği için', 'Soru çözmenin yalnızca sınavdan önceki son saatte yapıldığında etkili olduğu bilimsel olarak kanıtlandığı için', 'Konuyu hiç okumadan rastgele şık işaretlemenin tek başına tüm müfredatı öğrettiği için'], 'Test çözmek sadece öğrenileni ölçmez, bizzat öğrenmeyi üretir; erken aşamada yapılan düşük riskli testler ve ardından alınan geri bildirim, tekrar okumadan çok daha etkilidir.'),
  ('Üstbilişsel izleme doğruluğunu (kalibrasyon) ölçen bir deneyde, öğrencilerin sınav öncesi bekledikleri puan ile aldıkları gerçek puan karşılaştırılmaktadır; düşük başarılı öğrencilerin yüksek başarılı öğrencilere göre çok daha büyük "aşırı güven" (overconfidence) göstermesi "çifte yük" hipoteziyle nasıl açıklanır?', 'Doğru yanıtı üretmek için gereken bilgi ve beceri ile kendi yanıtının doğruluğunu değerlendirmek için gereken üstbilişsel bilgi aynı yetkinlik temelini paylaşır', ['Düşük başarılı öğrenciler sınav sorularını yüksek başarılılardan çok daha yavaş okuduğu için zaman kazanmak ister', 'Yüksek başarılı öğrencilerin tamamı öğrenilmiş çaresizlik yaşadığı için puanlarını kasıtlı olarak sıfır tahmin eder', 'Aşırı güven yalnızca sayısal derslerde görülür, sözel derslerde düşük başarılı öğrenciler her zaman tam isabetli tahmin yapar'], 'Dunning ve Kruger\'in çifte yük (dual burden) açıklamasına göre, bir alandaki bilgi eksikliği hem hata yapmaya yol açar hem de yapılan hatayı fark edecek üstbilişsel ölçütlerden yoksun bırakır.'),
  ('"Bağlamsal girişim etkisi" (contextual interference effect - Battig), çalışma sırasında yüksek düzeyde karışıklık ve değişkenlik içeren harmanlanmış koşulların neden ilk edinim aşamasında düşük, ancak kalıcılık ve transfer testlerinde yüksek performans ürettiğini hangi iki hipotezle açıklar?', 'Ayrıntılandırıcı karşılaştırma hipotezi ve eylem planını yeniden yapılandırma (unutma-yeniden kurma) hipotezi ile', ['Duyusal sönme hipotezi ve klasik koşullama genellemesi hipotezi ile', 'Sadece görsel kopyalama hipotezi ve tepki hızlanması hipotezi ile', 'Kısa süreli bellek taşması hipotezi ve bastırma savunması hipotezi ile'], 'Harmanlama sırasında ya görevler çalışma belleğinde bir arada karşılaştırılır (ayrıntılandırma) ya da her geçişte çözüm planı çalışma belleğinden silinip bir sonraki gelişte baştan yeniden kurulur (yeniden yapılandırma).'),
  ('Üniversite sınavına hazırlanan bir öğrenci yanlış yaptığı soruları kesip bir "hata defteri" oluşturmaktadır; bu uygulamanın üstbiliş ve aralıklı geri getirme ilkelerine tam uygun olması için nasıl yürütülmesi gerekir?', 'Sorunun altına doğru cevabı yazmamalı; neden hata yaptığını (kavram eksikliği mi, işlem hatası mı) analiz edip soruyu belirli gün aralıklarıyla yardımsız yeniden çözmelidir', ['Sorunun yanına öğretmeninin çözümünü renkli kalemlerle yapıştırıp her akşam yatmadan önce çözüme göz gezdirmelidir', 'Yanlış yaptığı soruları moralini bozmaması için bir kez inceledikten sonra çöpe atmalıdır', 'Aynı gün içinde o sorunun tıpatıp aynısını rakamlarını bile değiştirmeden on kez bakarak yazmalıdır'], 'Çözüme göz gezdirmek akıcılık yanılsaması yaratır; hatanın üstbilişsel nedenini teşhis etmek ve aralıklı olarak soruyu sıfırdan çözmek (geri getirme) gerçek kazanım sağlar.'),
  ('Geri getirme pratiğinin yalnızca test edilen bilgiyi değil, henüz öğrenilecek olan yeni bilgilerin kodlanmasını da kolaylaştırmasına "testin ileriye dönük etkisi" (forward testing effect / test-potentiated learning) denir; bu etkiyi açıklayan temel mekanizma nedir?', 'Ara testlerin önceki bölümlerden kaynaklanan ileriye ket vurmayı azaltması, dikkat dağınıklığını sıfırlaması ve daha etkili kodlama stratejilerine geçişi sağlaması', ['Test çözmenin beynin arka lobundaki görsel reseptör sayısını kalıcı olarak artırması', 'Önceki bilgilerin test edildiği anda uzun süreli bellekten tamamen silinerek yeni bilgilere boş yer açması', 'Sınav kaygısının adrenalin salgılatarak okuma hızını üç katına çıkarması'], 'Szpunar ve meslektaşlarının araştırmaları, bölümler arasına konan kısa testlerin zihin gezinmesini (mind wandering) azalttığını ve önceki listelerin yeni listelere ket vurmasını önlediğini göstermiştir.'),
  ('İki farklı çalışma programından Birinci Programda öğrenci konuyu çalışıp hemen ardından tek bir kapsamlı özet yazmakta ve bir daha konuya dönmemektedir; İkinci Programda ise öğrenci konuyu çalıştıktan 1 gün, 4 gün ve 12 gün sonra boş bir kağıda hatırladıklarını yazıp eksiklerini kaynaktan kontrol etmektedir. Toplam harcanan süre eşit olduğunda İkinci Programın üstün olmasının temel gerekçesi nedir?', 'Unutma başladıktan sonra yapılan aralıklı serbest hatırlama ve geri bildirim döngüsünün hem geri getirme yollarını güçlendirmesi hem de üstbilişsel kör noktaları onarması', ['Boş kağıda üç kez yazmanın el kaslarındaki motor belleği güçlendirerek bilişsel yükü sıfırlaması', 'Birinci Programda özet yazmanın derin işlemeyi tamamen engellemesi', 'İkinci Programda konunun ilk gün hiç anlaşılmadan doğrudan ezberlenmesi'], 'İkinci Program, aralıklı tekrar (spacing), serbest hatırlama (retrieval practice) ve üstbilişsel geri bildirim ilkelerini aynı anda birleştirdiği için aynı sürede çok daha yüksek kalıcılık üretir.'),
  ('Morris, Bransford ve Franks\'in "aktarıma uygun işleme" (transfer-appropriate processing) kuramı, Craik ve Lockhart\'ın "işleme düzeyleri" kuramına hangi kritik şerhi düşmüştür?', 'Bellek başarısı yalnızca kodlamanın mutlak derinliğine değil, bilginin kodlanma biçimi ile sınavda geri çağrılma biçimi arasındaki uyuma bağlıdır', ['Yüzeysel işleme her türlü sınav koşulunda anlamsal işlemeden daha yüksek hatırlama sağlar', 'Kodlama sırasında harcanan çabanın sınav başarısı üzerinde hiçbir etkisi yoktur', 'Anlamsal işleme yalnızca rakamların ezberlenmesinde işe yararken kelimelerde etkisizdir'], 'Örneğin sınavda kafiye sorulacaksa (sesbilimsel test), çalışma sırasında sesbilimsel kodlama yapanlar anlamsal kodlama yapanlardan daha başarılı olabilir; yani kodlama-test örtüşmesi belirleyicidir.'),
  ('Bir tıp öğrencisi yüzlerce farklı kalp ritim bozukluğu (EKG) grafiğini teşhis etmeyi öğrenirken hem "harmanlanmış çalışma" hem de "açıklayıcı geri bildirim" ilkelerini nasıl bütünleştirmelidir?', 'Farklı patolojilere ait EKG grafiklerini karışık sırada inceleyip önce kendi tanısını koymalı, ardından doğru tanıyı ve o grafiği benzerlerinden ayıran kritik dalga özelliğini kontrol etmelidir', ['Önce sadece normal EKG grafiklerine yüz kez bakmalı, sınav sabahı patolojik grafiklere göz atmalıdır', 'Her grafik türünün adını grafiğin üzerine büyük harflerle yazıp grafiklere sırayla bakarak okumalıdır', 'Tanı koymakta zorlandığı karmaşık grafikleri desteden çıkarıp sadece kolay bildiği grafikleri tekrar etmelidir'], 'Karışık sıra ayırt etmeyi (discriminative contrast), önce tahmin yürütmek geri getirmeyi, ayırt edici özelliği incelemek ise derin geri bildirimi sağlar.'),
  ('Öğrencilerin uzun bir ders videosu izlerken dikkatlerinin dağılması (zihin gezinmesi - mind wandering) ile üstbilişsel farkındalık (meta-awareness) arasındaki ilişki incelendiğinde hangi bulgu öne çıkmaktadır?', 'Zihin gezinmesi kaçınılmaz olarak başlasa da üstbilişsel farkındalığı yüksek öğrenciler koptuklarını erken fark edip videoyu geri sararak anlam kopukluğunu onarır', ['Üstbilişi güçlü bireylerin zihni yaşamları boyunca bir saniye bile dağılmaz', 'Videoların arasına kısa sorular eklemek zihin gezinmesini artırarak öğrenmeyi bozar', 'Zihin gezinmesi sırasında beyin videodaki bilgileri bilinçdışı olarak çok daha derin kodlar'], 'Üstbilişsel izleme dikkatin hiç dağılmamasını değil, dağıldığı anın fark edilip düzenleyici müdahale (yeniden odaklanma, geri dönme) yapılmasını sağlar; aralara konan testler de bu kopuşu azaltır.'),
  ('Bir öğrenci "Ben konuyu çalışırken müzik dinlemezsem ve televizyon açık olmazsa odaklanamıyorum, sessizlikte sıkılıyorum; üstelik bu şekilde ödevlerimi bitirebiliyorum" demektedir. Öğrenme bilimi açısından bu durum nasıl yorumlanmalıdır?', 'Arka plandaki sözel içerikli medya çalışma belleğinin fonolojik döngüsünü işgal ederek derin işlemeyi bozar; öğrenci duygusal konforu bilişsel verimlilikle karıştırmaktadır', ['Televizyon sesi beyindeki alfa dalgalarını güçlendirdiği için sözel metinlerin anlaşılmasını iki kat artırır', 'Ödevin tamamlanmış olması bilginin uzun süreli belleğe kalıcı olarak aktarıldığının kesin kanıtıdır', 'Sıkılma hissini önlemek için çalışma sırasında aynı anda üç farklı uyaran kanalına maruz kalmak en ideal üstbilişsel stratejidir'], 'Sözlü müzik ve konuşma içeren televizyon yayını, okunan metinle aynı sözel çalışma belleği kaynakları için yarışır; görevin bitirilmesi derin öğrenme gerçekleştiği anlamına gelmez.'),
  ('Koriat\'ın "ipucu kullanımı" (cue-utilization) çerçevesine göre, bireyler kendi öğrenme düzeylerini (JOL) değerlendirirken neden sıklıkla yanılgıya düşerler?', 'Uzun süreli bellekteki gerçek iz gücünü doğrudan göremedikleri için okuma hızı, yazı büyüklüğü veya tanıdıklık hissi gibi yanıltıcı yüzeysel ipuçlarına dayandıkları için', ['Öğrenme yargısı verirken her zaman geçmiş sınavlardaki en düşük notlarını baz aldıkları için', 'İnsan beyninde kendi bilgisini değerlendirmeye yarayan prefrontal ağlar hiç bulunmadığı için', 'Yalnızca çok zor sorularda aşırı güven, çok kolay sorularda ise sıfır güven gösterdikleri için'], 'Bireyler bellek izini doğrudan ölçemez; işlem akıcılığı gibi dolaylı ipuçlarını kullanır. Tanıdıklık ve akıcılık gibi içsel ama yüzeysel ipuçları ise kalıcılığı yansıtmadığı için yanılsama üretir.'),
  ('Kimya dersinde bağ türlerini (iyonik, kovalent, metalik) öğrenen bir sınıf için öğretmenin "karşılaştırmalı ayrıntılandırma ve geri getirme matrisi" tasarlaması istendiğinde en etkili etkinlik hangisidir?', 'Öğrencilere kaynak kapalıyken üç bağ türünü elektron davranışı, tanecik yapısı ve fiziksel özellikler boyutlarında karşılaştıran boş bir tabloyu doldurtup ardından eşli kontrol yaptırmak', ['Tahtaya dolu tabloyu yansıtıp öğrencilerden tabloyu defterlerine eksiksiz ve renkli kalemlerle geçirmelerini istemek', 'Her hafta yalnızca tek bir bağ türünü işleyip önceki bağ türlerinin adını bir daha hiç anmamak', 'Bağ türlerinin tanımlarını koro halinde sınıfa on kez yüksek sesle tekrar ettirmek'], 'Kaynak kapalıyken çok boyutlu karşılaştırma tablosu doldurmak; geri getirme pratiği, harmanlanmış ayırt etme ve derin anlamsal işlemeyi tek görevde birleştirir.'),
  ('Rohrer, Dedrick ve Stershic tarafından ortaokul matematik sınıflarında yürütülen uzun süreli saha araştırmasında, ev ödevlerini "harmanlanmış ve zamana yayılmış" olarak çözen öğrenciler, "blok" çözen öğrencilere kıyasla bir ay sonraki habersiz sınavda yaklaşık iki kat daha başarılı olmuştur; bu bulgunun eğitim tasarımı açısından temel çıkarımı nedir?', 'Ders kitaplarındaki alıştırmaların yalnızca o gün işlenen konuyu içermek yerine önceki ünitelerin soru tiplerini de karışık oranda barındıracak şekilde yapılandırılması gerektiği', ['Yeni bir matematik konusu anlatılırken ilk örneklerin bile öğrencilere hiç kural verilmeden tamamen karışık sorulması gerektiği', 'Matematik öğretiminde konu anlatımının tamamen kaldırılıp yalnızca sınav yapılması gerektiği', 'Blok çalışmanın ilk öğrenme aşamasında bile öğrencinin konuyu anlamasını imkansız kıldığı'], 'İlk kavram öğretiminde birkaç blok örnek anlaşılırlık için yararlıdır; ancak ardından gelen alıştırma ve ödevlerin önceki konularla harmanlanıp zamana yayılması kalıcı ustalık için şarttır.'),
  ('Karpicke ve Blunt\'ın Science dergisinde yayımlanan araştırmasında, karmaşık fen metinlerini çalışan bir grup metin açıkken ayrıntılı "kavram haritası" çizmiş, diğer grup ise metni kapatıp serbest "geri getirme pratiği" yapmıştır; bir hafta sonra hem anlamlı çıkarım sorularında hem de sonradan kavram haritası çizme testinde hangi grup üstün gelmiştir?', 'Geri getirme pratiği yapan grup, kavram haritası çizen gruba kıyasla hem çıkarım sorularında hem de bir hafta sonra bellekten kavram haritası oluşturmada daha yüksek başarı göstermiştir', ['Kavram haritası çizen grup görsel çalıştığı için tüm test türlerinde iki kat daha başarılı olmuştur', 'Geri getirme pratiği yalnızca ezber sorularda işe yaramış, çıkarım sorularında kavram haritası grubu üstün gelmiştir', 'Her iki grup da öğrencilerden kendi tahminleri sorulduğunda geri getirme pratiğinin daha etkili olacağını doğru öngörmüştür'], 'Katılımcıların çoğu kavram haritası çizmenin daha çok öğreteceğini tahmin etmiş (üstbilişsel yanılgı), ancak gerçek sonuçlarda aktif geri getirme pratiği derin anlamlı öğrenmede bile daha etkili çıkmıştır.'),
  ('Bir eğitim yazılımı şirketi "Uygulamamız yapay zeka ile öğrencinin hiç hata yapmamasını sağlıyor; öğrenci her soruyu %100 kolaylıkla doğru çözüyor ve hiç zorlanmadan motive oluyor" şeklinde tanıtım yapmaktadır. Bjork\'ün öğrenme bilimi ilkeleri açısından bu yazılımın pedagojik tasarımı nasıl eleştirilmelidir?', 'Hata olasılığını ve bilişsel zorlanmayı sıfırlamak kısa vadeli motivasyon ve akıcılık hissi yaratsa da arzu edilen zorlukları ortadan kaldırdığı için derin kodlama ve uzun vadeli kalıcılığı zayıflatır', ['Öğrencinin hiç hata yapmaması bilginin doğrudan uzun süreli belleğe yazıldığının kesin kanıtı olduğu için tasarım kusursuzdur', 'Hata yapmak sinir sisteminde geri dönüşsüz ket vurma yarattığı için eğitimde sıfır hata ilkesi tek geçerli ilkedir', 'Uygulamanın tek eksiği soruları çözmek yerine cevapları doğrudan ekranda hazır göstermemesidir'], 'Wilson ve meslektaşlarının optimal öğrenme (%85 doğruluk kuralı gibi) ve Bjork\'ün arzu edilen zorluklar çerçevesine göre, çok kolay görevler yeni öğrenme sinyali üretmez; hafif zorlanma ve geri bildirimli çaba gelişim için gereklidir.'),
  ('Sosyal bilimler dersinde bir tarihsel dönemin ekonomik, siyasal ve kültürel neden-sonuç ilişkilerini çalışan bir öğrencinin "çift yönlü sorgulayıcı ayrıntılandırma ve şema kurma" yapması için en üst düzey çalışma sorusu hangisidir?', 'Ekonomik kriz siyasal yapıyı nasıl dönüştürdü ve eğer bu ekonomik koşul farklı gelişseydi kültürel kurumlar bundan nasıl etkilenirdi?', ['Bu tarihsel dönemde padişah veya kral olan kişilerin doğum tarihleri küçükten büyüğe nasıl sıralanır?', 'Kitabın bu ünitesinde kaç adet harita ve kaç adet fotoğraf kullanılmıştır?', 'Siyasal olayların anlatıldığı paragrafta en çok tekrar eden bağlaç hangisidir?'], '"Nasıl" ve "eğer farklı olsaydı (karşı-olgusal düşünme)" soruları değişkenler arasındaki nedensel dokuyu derinlemesine işlemeyi ve esnek zihinsel modeller kurmayı sağlar.'),
  ('Kapur\'un "üretken başarısızlık" (productive failure) araştırma paradigmasında, yeni bir matematiksel kavramı öğrenmeden önce öğrencilerin kendi yöntemleriyle karmaşık bir problemi çözmeye çalışıp başarısız olmaları ve ardından doğrudan öğretim almaları, önce doğrudan kural anlatılıp sonra problem çözen gruba kıyasla neden daha derin kavramsal anlama üretmektedir?', 'Ön problem çözme çabası öğrencinin ön bilgilerini etkinleştirir, mevcut yöntemlerinin sınırlarını üstbilişsel olarak fark ettirir ve ardından anlatılan hedef kavramın kritik özelliklerini ayırt etmeye hazırlar', ['Başarısız olmak öğrencinin özgüvenini tamamen yıkarak öğretmenin söylediği her cümleyi sorgulamadan ezberlemesini sağlar', 'Doğrudan öğretim alan öğrenciler problemi çok hızlı çözdükleri için sınavda soruları okumadan işaretlerler', 'Üretken başarısızlık yönteminde öğrencilere hiçbir aşamada doğru formül ve açıklama verilmez'], 'Kapur\'un çalışmaları, yapılandırılmış keşif ve başarısızlık evresinin ardından gelen açıklayıcı öğretimin, doğrudan hazır formül verilmesine kıyasla kavramsal kavrayışı ve transferi belirgin biçimde güçlendirdiğini göstermiştir.'),
  ('Kirschner, Sweller ve Clark gibi bilişsel yük kuramcılarının "tamamen rehbersiz saf buluş yoluyla öğretime" yönelttikleri temel bilimsel eleştiri aşağıdakilerden hangisidir?', 'Acemi öğrenenlerin çalışma belleğini aşırı yükleyerek şema oluşumunu zorlaştırması ve kavram yanılgılarına yol açabilmesi', ['Öğrencilerin öğretmene olan duygusal bağlılığını gereğinden fazla artırarak bireysel özerkliği yok etmesi', 'Yalnızca sembolik temsil dönemindeki yetişkinlerde işe yarayıp çocuklarda hiçbir merak uyandırmaması', 'Kısa süreli belleğin kapasitesini sınırsız kabul ederek uzun süreli belleği tamamen devre dışı bırakması'], 'Yapı iskelesi olmayan saf keşif ortamlarında acemiler rastgele arama yaparken çalışma belleği kapasitesini tüketir; bu yüzden rehberli buluş önerilir.'),
  ('Vygotsky\'nin Yakınsak Gelişim Alanı kavramı ile geleneksel standart zeka (IQ) testleri karşılaştırıldığında Vygotsky açısından standart testlerin en önemli eksikliği nedir?', 'Yalnızca olgunlaşması tamamlanmış dünkü gelişim meyvelerini ölçüp tomurcuk halindeki yarınki gelişimi gözden kaçırması', ['Uygulama sırasında uzmanların öğrenciye çok fazla ipucu vererek puanları yapay biçimde yükseltmesi', 'Bireyin kültürden ve dilden edindiği sosyal becerileri biyolojik reflekslerden daha fazla ödüllendirmesi', 'Aynı kronolojik yaştaki tüm çocukların potansiyel öğrenme hızlarını birbirine eşit kabul etmesi'], 'Vygotsky\'ye göre bağımsız test puanı gelişimin geçmiş özetidir; asıl öğretimsel değer taşıyan gösterge rehberlikle açığa çıkan ZPD genişliğidir.'),
  ('Aynı bağımsız sınavdan 70 puan alan iki öğrenciden Ali, öğretmen ipucu verdiğinde 95 puanlık görevleri çözebilirken; Burak aynı ipuçlarıyla 75 puanlık görevlere çıkabilmektedir. Vygotsky\'ye göre bu durum nasıl yorumlanır?', 'Başlangıç düzeyleri eşit görünse de Ali\'nin Yakınsak Gelişim Alanı daha geniş olduğundan öğretime hazırbulunuşluk potansiyeli daha yüksektir', ['Her iki öğrencinin de mevcut gelişim düzeyi aynı olduğu için gelecekteki öğrenme hızları kesinlikle eşit olacaktır', 'Burak ipuçlarından etkilenmediği için bağımsız düşünme ve soyutlama becerisi Ali\'den çok daha ileridedir', 'Öğretmenin ipucu vermesi ölçme güvenirliğini bozduğu için her iki öğrencinin de gerçek düzeyi 70 olarak sabitlenmelidir'], 'ZPD kuramına göre aynı statik puana sahip bireylerin potansiyel gelişim alanları farklı olabilir ve öğretim bu dinamik farkı dikkate almalıdır.'),
  ('Bir okul yönetimi "Sınıfımızda yapılandırmacılığa geçtik; artık öğretmenler derste hiçbir açıklama yapmayacak ve yönlendirme sunmayacak, öğrenciler her şeyi kendi kendine bulacak" kararını almıştır. Bu karar eğitim kuramları açısından nasıl değerlendirilmelidir?', 'Yapılandırmacılığı "rehbersiz başıboşluk" ile karıştıran, yapı iskelesi ve kavramsal açıklama basamaklarını yok sayan hatalı bir uygulamadır', ['Radikal ve sosyal yapılandırmacılığın tüm bilimsel ilkelerini eksiksiz biçimde hayata geçiren ideal bir reformdur', 'Öğrencilerin çalışma belleği yükünü en aza indirerek tüm sınıfta hatasız ve hızlı öğrenmeyi garanti eden bir karardır', 'Bruner\'in sarmal program ve Vygotsky\'nin Yakınsak Gelişim Alanı kuramlarıyla tam uyum gösteren pedagojik bir yaklaşımdır'], 'Etkili yapılandırmacılık öğretmenin çekilmesini değil, yapı iskelesi kurarak, bilişsel çelişki yaratarak ve kavramları netleştirerek aktif rehberlik yapmasını gerektirir.'),
  ('Sarmal program yaklaşımıyla hazırlanan bir müfredatta öğretmenlerin konuları her yıl aynı derinlikte ve aynı örneklerle baştan anlatmaları durumunda ortaya çıkacak en ciddi pedagojik sorun nedir?', 'Sarmallığın "genişleme ve derinleşme" ilkesi bozularak programın bıktırıcı ve gelişimi durduran kısır bir döngüye dönüşmesi', ['Öğrencilerin alt sınıflarda edindikleri ön bilgilerin aşırı hızlı soyutlama nedeniyle tamamen unutulması', 'Disiplinlerarası bağlantıların gereğinden fazla güçlenerek ders sınırlarının ortadan kalkması', 'Buluş yoluyla öğretim stratejisinin kendiliğinden tam öğrenme modeline evrilmesi'], 'Sarmal program daire çizmek (aynı yere dönmek) değil, helezonik biçimde her dönüşte kavramsal düzeyi yukarı taşımaktır.'),
  ('Bruner\'in kavram öğretimi kuramına göre yeni ve tamamen yabancı bir soyut kavramla karşılaşan bir yetişkinin (örneğin karmaşık bir tıp cihazını öğrenen cerrahın) öğrenme süreci nasıl işler?', 'Sembolik dönemde olsa bile yabancı konuda önce eylemsel ve imgesel deneyimlere başvurup ardından sembolik ustalığa geçer', ['Yetişkin olduğu için somut deneme ve görsel şemalara hiç ihtiyaç duymadan yalnızca kullanım kılavuzunu okuyarak uzmanlaşır', 'Bilişsel esnekliğini yitirdiği için eylemsel döneme geri dönemez ve beceriyi yalnızca ezberleyerek uygular', 'Önce matematiksel denklemleri türetir, en son aşamada cihaza fiziksel olarak dokunmaya başlar'], 'Bruner\'in temsil biçimleri yaşla tamamen silinmez; yetişkinler de aşina olmadıkları zorlu alanlarda eylemsel ve imgesel destekten semboliğe doğru ilerler.'),
  ('Vygotsky geleneğindeki "kültürel araçlar" (dil, sayı sistemleri, haritalar, dijital yazılımlar) kavramının insan bilişi üzerindeki dönüştürücü etkisi aşağıdakilerden hangisidir?', 'Yalnızca işi hızlandırmakla kalmaz, bireyin dikkat, bellek ve problem çözme süreçlerinin zihinsel mimarisini yeniden örgütler', ['Zihinsel süreçlerin doğal biyolojik işleyişini hiç değiştirmeden sadece kas gücünden tasarruf edilmesini sağlar', 'Bireyin kendi başına düşünme yetisini körelterek insanı dışsal nesnelere tamamen bağımlı bir alıcıya indirger', 'Kültürden kültüre hiçbir farklılık göstermeyen evrensel ve doğuştan gelen sabit şemalar üretir'], 'Vygotsky\'ye göre psikolojik ve kültürel araçlar zihne dışarıdan eklenen basit aksesuarlar değil, düşünmenin doğasını niteliksel olarak dönüştüren aracılardır.'),
  ('Bir öğretmenin yapı iskelesi desteğini öğrenci görevi çoktan kavradığı halde uzun süre kesmeden sürdürmesi gelişimsel açıdan hangi olumsuz sonuca yol açar?', 'Öğrencinin öz-düzenleme becerisini ve özerkliğini ketleyerek öğrenilmiş bağımlılık geliştirmesine neden olur', ['Yakınsak Gelişim Alanı\'nın üst sınırını sınırsız biçimde genişleterek yaratıcı düşünmeyi doruğa çıkarır', 'Bilişsel dengesizliği sürekli canlı tutarak öğrencinin kendi şemalarını bağımsızca kurmasını hızlandırır', 'Bilginin sembolik düzeyden eylemsel düzeye doğru kalıcı biçimde transfer edilmesini kolaylaştırır'], 'Zamanında geri çekilmeyen (fading yapılmayan) aşırı destek, yapı iskelesinin özerkleştirici amacına ters düşerek bağımlılık yaratır.'),
  ('Piaget\'nin "akran etkileşimi" ile Vygotsky\'nin "akran etkileşimi" vurguları bilişsel mekanizma açısından karşılaştırıldığında en ince kuramsal ayrım hangisidir?', 'Piaget eşit statüdeki akranlar arası fikir çatışmasının bilişsel dengesizlik yarattığını, Vygotsky ise daha yetkin akranın ZPD içinde rehberlik sunduğunu öne çıkarır', ['Piaget yalnızca yetişkin-çocuk etkileşimini değerli bulurken Vygotsky akranlar arası her türlü iletişimi gelişim için zararlı görür', 'Piaget akranların birbirini taklit ederek koşullanmasını, Vygotsky ise akranların birbirinden tamamen bağımsız bireysel keşfini savunur', 'Her iki kuramcı da akran etkileşiminin yalnızca asimetrik otorite ilişkisi içinde gerçekleştiğinde şema kurduğunu iddia eder'], 'Piaget\'de eşit akranlar arası sosyo-bilişsel çatışma benmerkezciliği kırarken, Vygotsky\'de asimetrik yetkinlikteki akranla iş birliği kültürel aktarımı ve ZPD gelişimini sağlar.'),
  ('Yapılandırmacı bir fen dersinde öğrencilerin deney verilerinden hareketle "Bitkiler ağırlıklarının tamamını topraktaki çamurdan alır" şeklinde bilimsel olarak yanlış bir ortak sonuca vardıkları görülmüştür. Öğretmenin en doğru pedagojik müdahalesi ne olmalıdır?', 'Topraksız suda büyüyen bitki örneği veya Van Helmont deneyi verilerini sunarak mevcut sonuçlarını sorgulatacak yeni bir bilişsel çelişki yaratmak', ['Yapılandırmacılıkta her öznel kurgu geçerli sayıldığı için öğrencilerin bu yanlış sonucunu bilimsel gerçek olarak onaylamak', 'Deney yöntemini derhal terk edip fotosentez denklemini ceza ödevi olarak öğrencilere yirmi kez yazdırmak', 'Öğrencilerin deney defterlerini toplayıp tüm sınıfa sıfır puan vererek konuyu bir sonraki yıla ertelemek'], 'Yapılandırmacılık "ne bulursan doğrudur" göreceliği değildir; öğretmen karşıt kanıtlarla yapı iskelesi kurarak öğrencilerin bilimsel açıdan geçerli modellere ulaşmasını sağlar.'),
  ('Wood, Bruner ve Ross (1976) tarafından tanımlanan yapı iskelesi işlevlerinden "hayal kırıklığını kontrol etme" ve "kritik özellikleri belirginleştirme" bir arada düşünüldüğünde öğretmenin görevi nedir?', 'Görevin bilişsel zorluğunu tamamen yok etmeden, öğrencinin duyuşsal olarak kopmasını önleyip dikkatini çözümün kilit noktalarına odaklamak', ['Görevin tüm zor kısımlarını müfredattan çıkararak öğrencinin hiçbir çaba harcamadan sürekli başarı hissi yaşamasını sağlamak', 'Öğrenci hata yaptığında anında sert eleştiriler yönelterek dikkat düzeyini kaygı yoluyla en üst seviyede tutmak', 'Çözüm için gereken tüm adımları numaralı bir reçete halinde verip öğrenciden sadece mekanik uygulama beklemek'], 'Etkili yapı iskelesi hem görevin özünü koruyup önemli ipuçlarını öne çıkarır hem de aşırı stresin öğrenmeyi kilitlemesini engeller.'),
  ('Bruner\'in sarmal program anlayışı ile Piaget\'nin bilişsel gelişim ve şema kuramı arasındaki kuramsal bütünlük nasıl açıklanabilir?', 'Sarmal programdaki her yeni dönüş, önceki yıllarda kurulan şemaları özümseme zemini olarak kullanıp daha karmaşık şemalara uyumsamayı tetikler', ['Sarmal program Piaget\'nin şema kavramını tamamen reddederek bilginin boş bir levhaya doğrusal olarak kazınmasını temel alır', 'Her iki yaklaşım da soyut kavramların yalnızca üniversite yıllarında ilk kez müfredata alınması gerektiğini savunur', 'Piaget\'nin korunum ilkesi gereği müfredattaki bilgi miktarı yıllar geçse de hiçbir şekilde artırılamaz'], 'Önceki sarmal halkada oluşan bilişsel yapılar yeni öğrenmeler için ön şema görevi görür ve artan derinlik uyumsama yoluyla kavramsal büyümeyi sağlar.'),
  ('Geleneksel eğitimde bilginin "tuğla duvar örer gibi" üst üste ve değişmez parçalar halinde biriktirildiği varsayımı, yapılandırmacı epistemoloji açısından neden eleştirilir?', 'Yeni öğrenmelerin eski bilgilere sadece eklenmediğini, mevcut kavramsal ağı baştan aşağı yeniden örgütleyip dönüştürdüğünü göz ardı ettiği için', ['İnsan belleğinin görsel imgelerden çok sözel tekerlemeleri saklamaya elverişli olduğunu hesaba katmadığı için', 'Öğrencilerin okul dışında hiçbir yaşam deneyimine sahip olmadığını bilimsel olarak kanıtladığı için', 'Bilginin yalnızca grup çalışmalarında değil bireysel okumalarda da aynı hızda ezberlendiğini unuttuğu için'], 'Yapılandırmacılıkta öğrenme kümülatif bir yığılma değil, yeni deneyimlerle tüm kavramsal ağın yapısal olarak dönüşmesidir.'),
  ('Vygotsky\'nin "oyun" kavramına ilişkin analizinde, hayali oyun oynayan (örneğin bir sopayı at gibi kullanan) okul öncesi bir çocuğun kendi Yakınsak Gelişim Alanı\'nı oluşturduğu iddiasının dayanağı nedir?', 'Oyunda çocuğun anlık dürtülerini bastırıp rolün gerektirdiği kurallara uyarak gerçek yaşamdaki yaşından bir baş boyu daha olgun davranabilmesi', ['Oyun sırasında çocuğun yetişkin dünyasından tamamen koparak dil ve sembol kullanımını geçici olarak durdurması', 'Sopayı at sanmasının bilişsel gerçeklik algısını bozarak çocuğu somut işlemler döneminden uzaklaştırması', 'Oyunun hiçbir kural içermemesi sayesinde çocuğun öz-düzenleme yapma zorunluluğundan kurtulması'], 'Sembolik oyunda nesne ile anlam ayrışır (sopa at olur) ve çocuk üstlendiği sosyal rolün kurallarına gönüllü uyarak üst düzey öz-denetim sergiler.'),
  ('Bir yazılım eğitmeni, algoritma mantığını öğretirken önce öğrencilere kilitli bir kutuyu açmak için fiziksel kartlarla komut dizisi kurdurmakta, sonra akış şeması çizdirmekte, en son Python sözdizimiyle kod yazdırmaktadır. Öğrenciler hata aldığında ise doğrudan kodu düzeltmek yerine "7. satırdaki döngü koşulun sence ne zaman durur?" diye sormaktadır. Eğitmen hangi iki yaklaşımı sentezlemiştir?', 'Bruner\'in temsil aşamaları ile Vygotsky temelli sorgulayıcı yapı iskelesini', ['Skinner\'ın kademeli yaklaştırması ile Ausubel\'in anlamlı sunuş modelini', 'Pavlov\'un klasik koşullanması ile sabit oranlı pekiştirme tarifesini', 'Doğrusal program tasarımı ile norm dayanaklı çoktan seçmeli ölçmeyi'], 'Fiziksel karttan şemaya ve koda geçiş Bruner\'in eylemsel-imgesel-sembolik sırasını; hatayı doğrudan düzeltmeyip yönlendirici soru sormak ise yapı iskelesini yansıtır.'),
  ('Sosyal yapılandırmacı "karşılıklı öğretim" (reciprocal teaching) tekniğinde öğretmen ve öğrencilerin sırayla özetleme, soru sorma, açıklama ve tahmin etme rollerini üstlenmeleri hangi kuramsal mekanizmayı çalıştırır?', 'Üstbilişsel okuduğunu anlama stratejilerinin sosyal diyalog içinde görünür kılınarak ZPD aracılığıyla bireysel zihne içselleştirilmesini', ['Metnin anlamını tartışmadan en hızlı okuyan öğrencinin ödüllendirilerek okuma hızının mekanik olarak artırılmasını', 'Öğretmenin sınıf yönetimini tamamen bırakarak ders içeriğinin rastgele sohbet konularına kaydırılmasını', 'Yalnızca işitsel öğrenme stiline sahip öğrencilerin başarılı olacağı tek boyutlu bir ortam kurulmasını'], 'Palincsar ve Brown\'un Vygotsky temelli karşılıklı öğretim modelinde, dışsal sosyal diyalogla yürütülen stratejiler zamanla öğrencinin içsel okuma alışkanlığına dönüşür.'),
  ('"Yapılandırmacı değerlendirme yalnızca süreç içinde yapılır, dönem sonunda hiçbir şekilde ürün veya kazanım değerlendirmesi yapılamaz" görüşü ölçme ve değerlendirme ilkeleri açısından nasıl değerlendirilmelidir?', 'Yanlıştır; yapılandırmacılık süreci merkeze alsa da öğrencinin ulaştığı kavramsal bütünlüğü ve üst düzey transfer becerisini otantik ürünlerle de değerlendirir', ['Doğrudur; yapılandırmacı yaklaşımda herhangi bir performans ürününe bakmak davranışçı kurama kesin geri dönüş anlamına gelir', 'Doğrudur; çünkü radikal yapılandırmacılığa göre hiçbir öğrencinin öğrenip öğrenmediği dışarıdan gözlemlenemez', 'Yanlıştır; çünkü yapılandırmacılıkta süreç hiç izlenmez, yalnızca yıl sonundaki çoktan seçmeli test puanlarına bakılır'], 'Yapılandırmacı yaklaşımda biçimlendirici (süreç) değerlendirme ağırlıklıdır ancak performans görevleri, projeler ve portfolyolarla anlamlı çıktılar da bütüncül biçimde değerlendirilir.'),
  ('Bruner\'in buluş yoluyla öğretiminde "sezgisel düşünme" ile "analitik düşünme" arasındaki ilişki nasıl kurgulanmıştır?', 'Öğrencinin önce bütünü kavrayıp eğitimli tahminler yürüterek (sezgisel) hipotez üretmesi, ardından bunu adım adım kanıtlayarak (analitik) doğrulaması beklenir', ['Sezgisel düşünmenin bilimsel hatalara yol açtığı varsayılarak sınıfta tahmin yürütülmesi kesinlikle yasaklanır', 'Analitik düşünmenin yaratıcılığı öldürdüğü savunularak matematiksel kanıtların müfredattan çıkarılması önerilir', 'Sezgisel düşünme yalnızca sanat derslerine, analitik düşünme ise yalnızca fen ve matematik derslerine özgü sayılır'], 'Bruner, bilim insanları gibi öğrencilerin de önce cesur sezgisel sıçramalarla hipotez kurmasını, sonra analitik yöntemlerle bu hipotezleri sınamasını önemser.'),
  ('Bilişsel yapılandırmacılıkta yeni bir bilginin "anlamlı" biçimde inşa edilebilmesi ile ezberlenmesi arasındaki zihinsel yapı farkı nedir?', 'Anlamlı inşada yeni bilgi mevcut şema ağıyla çoklu mantıksal bağlar kurarken, ezberde mevcut şemalarla ilişkilendirilmeden yalıtık biçimde depolanır', ['Anlamlı inşada bilgi yalnızca duyusal kayıtta tutulurken, ezberde doğrudan uzun süreli işlemsel belleğe aktarılır', 'Ezberlenen bilgiler bilişsel uyumsamayı en üst düzeye çıkarırken, yapılandırılan bilgiler şemaları tamamen siler', 'Her iki süreç de zihinde aynı nörobilişsel ağları kurar ancak yalnızca tekrar sayıları bakımından farklılaşır'], 'Yapılandırılmış bilgi zengin şematik bağlantılar içerdiği için farklı bağlamlara transfer edilebilir; yalıtık ezber bilgi ise unutulmaya ve atıl kalmaya mahkumdur.'),
  ('Farklı sosyoekonomik ve kültürel geçmişlerden gelen öğrencilerin bulunduğu bir sınıfta Vygotsky\'nin sosyokültürel kuramını benimseyen bir öğretmenin ders tasarımını nasıl şekillendirmesi en tutarlıdır?', 'Öğrencilerin aile ve kültürlerinden getirdikleri "bilgi fonlarını" (yaşam deneyimlerini) yeni akademik kavramlar için yapı iskelesi köprüsü olarak kullanması', ['Kültürel farklılıkların akademik öğrenmeyi bozacağı düşüncesiyle öğrencilerin günlük yaşam deneyimlerini sınıf kapısının dışında tutması', 'Belirli bir kültürün örneklerini tek standart kabul edip diğer öğrencilerin farklı anlamlandırma biçimlerini eksiklik olarak etiketlemesi', 'Sosyal etkileşimi en aza indirerek tüm öğrencilere bireysel kulaklıklarla standartlaştırılmış ses kayıtları dinletmesi'], 'Sosyokültürel kurama göre bireyin zihinsel araçları kendi kültürel bağlamında şekillenir; bu yerel deneyimleri dersle bütünleştirmek ZPD içinde anlamlı köprüler kurar.'),
  ('Carol Dweck, son yıllardaki çalışmalarında eğitimciler arasında yayılan "sahte gelişim zihniyeti" (false growth mindset) uygulamalarını sert biçimde eleştirmiştir. Aşağıdakilerden hangisi sahte gelişim zihniyetine örnektir?', 'Stratejisi yanlış olduğu için hiç ilerleyemeyen bir öğrenciye yeni yöntem öğretmeden sadece "Harika çabaladın, denemeye devam et!" diyerek kuru çabayı övmek', ['Öğrencinin nerede takıldığını analiz edip alternatif problem çözme yolları denemesine rehberlik etmek', 'Başarısızlık sonrasında sonucu gizlemek yerine öğrenme sürecindeki eksik halkaları şeffafça tartışmak', 'Zorlayıcı görevlerde gerektiğinde uzmanlardan ve akranlardan yardım istemenin gelişimin bir parçası olduğunu vurgulamak'], 'Dweck\'e göre gelişim zihniyeti yalnızca "daha çok uğraş" demek değildir; işe yaramayan yöntemi ısrarla tekrarlamak yerine yeni stratejiler aramak ve geri bildirimle öğrenme odaklı ilerlemektir.'),
  ('Bandura\'nın "öz-yeterlik" kavramı ile Julian Rotter\'ın "denetim odağı" (locus of control) kavramı arasındaki kuramsal ayrım nasıl ifade edilir?', 'Öz-yeterlik "Bu davranışı başarıyla icra edebilir miyim?" inancıyken, denetim odağı "Davranışımın sonuçları benim eylemlerime mi yoksa şans ve kadere mi bağlı?" inancıdır', ['Öz-yeterlik sonuçların tamamen şansa bağlı olduğunu savunurken, içten denetim odağı bireyin hiçbir şeyi değiştiremeyeceğini savunur', 'Her iki kavram da bireyin genel zeka bölümünü (IQ) ölçmek için kullanılan eş anlamlı terimlerdir', 'Denetim odağı yalnızca sporda geçerliyken, öz-yeterlik yalnızca edebiyat derslerinde geçerlidir'], 'Bir öğrenci "Çok iyi çalışanlar yüksek not alır" diyerek içsel denetim odağına sahip olabilir, ancak "Ben o kadar iyi çalışacak kapasitede değilim" diyerek düşük öz-yeterlik yaşayabilir.'),
  ('Bandura kuramındaki "yeterlik beklentisi" (efficacy expectation) ile "sonuç beklentisi" (outcome expectation) ayrımı düşünüldüğünde; mülakatta tüm soruları mükemmel yanıtlayabileceğine inanan (yüksek öz-yeterlik) bir adayın, kurumda ağır torpil ve kayırmacılık olduğunu bildiği için başvurmaması hangi durumu yansıtır?', 'Yüksek yeterlik beklentisine karşın düşük sonuç beklentisinin harekete geçmeyi engellemesini', ['Düşük yeterlik beklentisine karşın yüksek sonuç beklentisinin kaygı yaratmasını', 'Dolaylı pekiştirme sonucunda adayın mülakat becerilerini unutmasını', 'Sabit zihniyet nedeniyle adayın kendi mesleki bilgisinden şüphe duymasını'], 'Yeterlik beklentisi "Ben bu performansı gösterebilir miyim?", sonuç beklentisi ise "Bu performansı gösterirsem beklediğim adil sonucu alır mıyım?" sorusudur; çevresel adaletsizlik sonuç beklentisini kırar.'),
  ('Bir okulda öğrencilerin öz-yeterliğini artırmak isteyen rehberlik servisi, sınav sorularını son derece kolaylaştırarak tüm öğrencilerin 100 tam puan almasını sağlamıştır. Bandura ve Vygotsky kuramları birlikte değerlendirildiğinde bu uygulamanın uzun vadedeki sakıncası nedir?', 'Çaba gerektirmeyen yapay başarılar dayanıklı öz-yeterlik üretmez; öğrenciler gerçek bir zorlukla ve ZPD içi görevle karşılaştıklarında hızla kırılganlık yaşarlar', ['Kolay sınavlar öğrencilerin çalışma belleğini aşırı yükleyerek kavram yanılgılarına neden olur', 'Tüm öğrencilerin yüksek not alması Öz-Belirleme Kuramı\'ndaki ilişkili olma ihtiyacını yok eder', 'Yüksek not alan öğrencilerde dolaylı ceza etkisi oluşarak okula devamsızlık artar'], 'Bandura\'ya göre çok kolay elde edilen başarılar kişiyi çabuk sonuca alıştırır; sağlam ve dirençli öz-yeterlik ancak anlamlı engellerin çabayla aşılmasıyla (zorlu ustalık deneyimleriyle) kazanılır.'),
  ('Öz-Belirleme Kuramı\'ndaki dışsal güdülenme sürekliliği incelendiğinde "içe yansıtılmış düzenleme" (introjected regulation) ile "özdeşleşmiş düzenleme" (identified regulation) arasındaki ince fark nedir?', 'İçe yansıtılmışta öğrenci suçluluk, utanç veya mahcup olma kaygısıyla ders çalışırken; özdeşleşmişte konuyu kendi gelecek hedefleri için kişisel olarak anlamlı bulduğu için çalışır', ['İçe yansıtılmışta öğrenci konuya saf bir merak ve oyun hazzı duyarken; özdeşleşmişte yalnızca fiziksel dayak korkusuyla hareket eder', 'Her iki düzenleme türü de güdülenmeme (amotivasyon) ile tamamen aynı psikolojik sonuçları doğurur', 'İçe yansıtılmış düzenleme tam özerkliği temsil ederken, özdeşleşmiş düzenleme en katı dışsal baskıyı temsil eder'], 'Suçluluktan kaçmak veya gururu korumak için çalışmak (içe yansıtma) hala içsel bir baskı barındırır; oysa etkinliğin değerini bilinçli olarak sahiplenmek (özdeşleşme) çok daha özerktir.'),
  ('Bir öğretmenin sınıfta gelişim zihniyetini teşvik ettiğini söylemesine rağmen dönem sonunda yalnızca tek bir sınava dayalı not verip hataların telafisine veya ödevlerin düzeltilip yeniden sunulmasına hiç izin vermemesi nasıl değerlendirilmelidir?', 'Söylem ile değerlendirme uygulaması çelişmektedir; hatalardan öğrenmeye ve gelişimi kanıtlamaya fırsat tanımayan katı notlandırma fiilen sabit zihniyeti ödüllendirir', ['Değerlendirme sisteminin tek sınava dayanması gelişim zihniyetini güçlendiren en etkili yapı iskelesi yöntemidir', 'Öğrencilerin ilk denemede hatasız olmasını şart koşmak içsel güdülenmeyi ve özerkliği en üst düzeye çıkarır', 'Söylem yeterli olduğu için notlandırma biçiminin öğrencilerin zihniyet yapısı üzerinde hiçbir etkisi olmaz'], 'Sınıfın yapısal kuralları ve değerlendirme rejimi revizyona ve gelişime kapalıysa, öğretmenin sözel "gelişim zihniyeti" mesajları öğrenciler tarafından inandırıcı bulunmaz.'),
  ('Yüksek öz-yeterlik algısının öğrenme sürecinde nadiren de olsa "olumsuz" bir etki yaratabileceği özel durum aşağıdakilerden hangisidir?', 'Hazırlık aşamasında aşırı özgüvene dönüşerek öğrencinin görevi hafife almasına ve yeterli çalışma süresini ayırmamasına yol açması', ['Öğrencinin sınav sırasında zor sorular karşısında sakin kalarak analitik düşünmesini sağlaması', 'Başarısızlık sonrasında bireyin yeni çözüm stratejileri arayarak toparlanma hızını artırması', 'Öğrencinin üst düzey akademik hedefler belirleyerek içsel merakını sürdürmesi'], 'Performans anında yüksek öz-yeterlik her zaman avantajlıdır; ancak hazırlık aşamasında gerçekçi olmayan aşırı öz-yeterlik bazen "zaten biliyorum" rehavetiyle eksik hazırlığa neden olabilir.'),
  ('Matematikte kesirler konusunda sürekli başarısız olup "Ben matematik özürlüyüm" diyen bir 6. sınıf öğrencisi için yapılandırmacı, sosyal bilişsel ve gelişim zihniyeti ilkelerini birleştiren en kapsamlı müdahale planı hangisidir?', 'Somut kesir modelleriyle ZPD içinde yapı iskelesi kurup adım adım küçük ustalık başarıları yaşatmak ve süreçteki strateji gelişimini vurgulayarak geri bildirim vermek', ['Öğrenciyi sınıfın önünde tahtaya kaldırıp çözemediği her soru için teneffüse çıkmasını yasaklayarak dışsal baskı uygulamak', 'Öğrencinin sayısal zekasının düşük olduğunu kabul edip onu matematik derslerinden tamamen muaf tutarak sadece resim dersine yönlendirmek', 'Hiçbir konu anlatımı ve ipucu vermeden 100 soruluk zor bir test ödevi verip "Sen dahisin, yaparsın" diyerek yalnız bırakmak'], 'Somut materyal ve yapı iskelesi (Bruner/Vygotsky), kademeli ustalık deneyimi (Bandura öz-yeterlik) ve strateji odaklı geri bildirim (Dweck gelişim zihniyeti) bütüncül iyileşme sağlar.'),
  ('Bir eğitim politikası uzmanı "Öğrencilerin içsel güdülenmesini korumak için okullarda her türlü geri bildirim, not, karne ve başarı belgesi tamamen kaldırılmalıdır" önerisini sunmuştur. Öz-Belirleme Kuramı açısından bu öneri neden eksiktir?', 'Sorun geri bildirimin varlığı değil kontrol edici dilidir; yeterlik ihtiyacını besleyen yapıcı ve bilgilendirici geri bildirimlerin tamamen kesilmesi öğrencide belirsizlik ve güdülenmeme yaratır', ['Öz-Belirleme Kuramı maddi para ödüllerinin ve sert cezaların her derste zorunlu olarak kullanılmasını şart koşmaktadır', 'Öğrenciler doğuştan tamamen tembel oldukları için dışsal korku olmadan hiçbir konuyu merak etmezler', 'Karnelerin kaldırılması yalnızca sabit zihniyete sahip öğrencilerin öz-yeterliğini en üst düzeye çıkarır'], 'İçsel güdülenmenin üç ayağından biri "yeterlik" (competence) hissidir; bireyin ne kadar ilerlediğini gösteren bilgilendirici geri bildirim olmadan yeterlik algısı kör kalır.'),
  ('Carol Dweck ve meslektaşlarının nörobilişsel (ERP/beyin dalgası) araştırmalarında, sabit zihniyetli bireyler ile gelişim zihniyetli bireylerin bir soruda "hata yaptıklarını öğrendikleri an" beyin etkinlikleri nasıl farklılaşmıştır?', 'Gelişim zihniyetlilerde hatayı düzeltici bilgiye yönelik dikkat ve derin işleme sinyalleri yükselirken, sabit zihniyetlilerde tehdit algısıyla düzeltici bilgiye dikkat hızla kapanmaktadır', ['Sabit zihniyetli bireylerin beyinleri hata anında yeni sinaptik bağlantıları gelişim zihniyetlilerden on kat daha hızlı kurmaktadır', 'Her iki grupta da hata bilgisinden sonra hiçbir elektriksel beyin etkinliği gözlenmemektedir', 'Gelişim zihniyetli bireyler doğru cevabı hiç merak etmeyip yalnızca aldıkları puana odaklanmaktadır'], 'Sabit zihniyet hatayı benlik tehdidi saydığı için öğretici açıklamadan kaçınır; gelişim zihniyeti ise hatayı öğrenme sinyali gördüğü için düzeltici geri bildirimi aktif olarak işler.'),
  ('Sosyal öğrenme kuramında medya, dijital oyunlar ve sosyal ağların "sembolik modelleme" gücü geleneksel yüz yüze modellemeden hangi yönüyle ayrışır?', 'Fiziksel mekan sınırlarını aşarak tek bir sembolik modelin aynı anda milyonlarca gözlemciye yeni normlar, tutumlar ve davranış kalıpları aktarabilmesiyle', ['Sembolik modellerin dikkat ve hatırda tutma süreçlerine hiç gerek kalmadan bilinçaltına doğrudan yerleşmesiyle', 'Dijital ortamdaki modellerin hiçbir zaman dolaylı pekiştirme veya dolaylı duygu etkisi yaratamamasıyla', 'Yalnızca yetişkinlerin sembolik modellerden etkilenip çocukların ekrandaki davranışları hiç taklit etmemesiyle'], 'Bandura\'ya göre kitap, televizyon ve dijital medyadaki sembolik modeller, yakın çevrede bulunmayan davranış örüntülerini ve kültürel değerleri geniş kitlelere yayma gücüne sahiptir.'),
  ('Bir öğretmenin sınıfta iş birlikli öğrenme grupları kurarken aynı zamanda yıl sonunda sadece "sınıf birincisi, ikincisi ve üçüncüsü" seçip diğer tüm öğrencileri başarısız ilan eden sert bir çan eğrisi uygulaması pedagojik olarak nasıl değerlendirilmelidir?', 'Sıfır toplamlı rekabetçi ödül yapısı arkadaşın başarısını kendi kaybı haline getirdiğinden, sosyal yapılandırmacı iş birliğini, ilişkili olma ihtiyacını ve ustalık yönelimini baltalar', ['Rekabetçi sıralama Vygotsky\'nin akran aracılı yapı iskelesi sürecini en verimli hale getiren temel koşuldur', 'Çan eğrisi tüm öğrencilerde gelişim zihniyetini ve öz-yeterlik algısını eşit biçimde yükseltir', 'Öz-Belirleme Kuramı\'na göre başkalarını elemek insanın en temel içsel psikolojik ihtiyacıdır'], 'Başkasının kaybetmesi üzerine kurulu norm dayanaklı kıt ödül sistemleri yardımlaşmayı keser, performans-kaçınma kaygısını artırır ve öğrenme topluluğu ruhunu zedeler.'),
  ('Bruner\'in "öğrenmeye yönelik içsel ödüller" vurgusu ile Bandura\'nın "öz-pekiştirme" (self-reinforcement) kavramı birlikte ele alındığında özerk bir öğrenenin motivasyon kaynağı nasıl dönüşür?', 'Başlangıçta dışsal rehber ve dönütlerle desteklenen öğrenen, zamanla kendi standartlarını karşıladığında duyduğu içsel tatmin ve keşif sevinciyle kendi kendini güdüleyen bir özneye dönüşür', ['Öğrenci yaş aldıkça içsel merakını tamamen kaybederek yalnızca maddi teşviklerle çalışan bir yapıya evrilir', 'Öz-pekiştirme bireyin hiçbir hedef koymadan her davranışını rastgele ödüllendirmesi anlamına gelir', 'Bruner ve Bandura insanın kendi davranışlarını değerlendirme kapasitesine sahip olmadığını savunur'], 'Hem Bruner\'in keşif hazzı hem Bandura\'nın içsel standartlara dayalı öz-pekiştirmesi, bireyin dışsal pekiştireç bağımlılığından kurtulup yaşam boyu özerk öğrenen olmasını açıklar.'),
  ('Eğitimde oyunlaştırma (gamification) uygulamalarında rozet, puan tablosu ve liderlik sıralamasının aşırı ve tek odak haline getirilmesi güdülenme kuramları ışığında nasıl değerlendirilmelidir?', 'Anlamlı öğrenme görevleri ve yeterlik geri bildirimiyle bütünleşmeyen yüzeysel puan/rozet yarışı, dikkati içerikten koparıp geçici dışsal güdülenmeye hapseder', ['Rozet ve liderlik tablosu içerik ne kadar anlamsız olursa olsun her öğrencide kalıcı içsel merak uyandırır', 'Liderlik tablosunun en altında kalan öğrencilerde öz-yeterlik algısı her zaman en yüksek seviyeye ulaşır', 'Oyunlaştırma unsurları Öz-Belirleme Kuramı\'ndaki özerklik ihtiyacını koşulsuz biçimde garanti altına alır'], 'Etkili oyunlaştırma özerklik, anlamlı zorluk ve ustalık gelişimini desteklemelidir; salt puan ve sıralama yarışı içsel öğrenme amacının önüne geçebilir.'),
  ('Yapılandırmacılık, Vygotsky\'nin sosyokültürel kuramı, Bandura\'nın sosyal bilişsel kuramı ve Dweck\'in gelişim zihniyeti çağdaş eğitim psikolojisinde hangi ortak "öğrenen insan" anlayışında birleşirler?', 'Öğreneni çevresel uyarıcıların veya sabit genlerin pasif alıcısı değil; anlam kuran, sosyal etkileşimle gelişen ve öz-düzenleme yapabilen aktif bir özne olarak görmede', ['İnsan zihnini dış dünyadaki bilgileri olduğu gibi kaydeden boş bir levha (tabula rasa) olarak tanımlamada', 'Eğitimin tek amacının standart testlerde öğrencileri birbirleriyle yarıştırıp elemek olduğunu savunmada', 'Öğretmeni sınıftaki tek bilgi otoritesi ve davranış biçimlendiricisi olarak konumlandırmada'], 'Bu kuramların tamamı mekanik davranışçılığın ve katı kalıtımcılığın ötesine geçerek bireyin aktif bilişsel, sosyal ve gelişimsel eylemliliğini (agency) merkeze alır.'),
  ('Çok kolay soruların yer aldığı bir sınavda çan eğrisi (bağıl ölçüt) uygulandığında ortaya çıkabilecek en temel pedagojik sorun aşağıdakilerden hangisidir?', 'Yüksek puan almasına rağmen grup ortalamasının altında kalan öğrencilerin başarısız sayılması', ['Tüm öğrencilerin hedeflenen kritik kazanımlara ulaşmadan doğrudan dersi geçmesi', 'Öğretmenin sınav öncesinde belirlediği sabit geçme barajının geçerliliğini koruması', 'Sınavın kapsam geçerliliğinin kendiliğinden yükselerek tüm üniteleri temsil etmesi'], 'Çok kolay bir sınavda grup ortalaması çok yükseleceğinden, kazanımların çoğunu edinen bir öğrenci bile ortalamanın altında kalıp başarısız sayılabilir.'),
  ('Hedef davranışların kritik olduğu bir ehliyet direksiyon sınavında bağıl ölçüt kullanılması hangi istenmeyen sonuca yol açabilir?', 'Tüm adayların kötü araç kullandığı bir grupta yetersiz sürücülere ehliyet verilmesi', ['Trafik kurallarını eksiksiz uygulayan adayların tamamının sınavdan elenmesi', 'Değerlendirme kriterlerinin sınav öncesinde adaylar tarafından net biçimde bilinmesi', 'Sürüş güvenliği standartlarının her sınav döneminde aynı sabitlikte korunması'], 'Bağıl ölçütte başarı gruba bağlı olduğundan, grubun genel olarak başarısız olduğu bir uygulamada ortalamanın biraz üstündeki yetersiz kişiler başarılı sayılabilir.'),
  ('Bir aşçının çorbanın tadına mutfakta pişirme aşamasında bakıp tuz eklemesi ile müşterinin masada çorbayı içip puan vermesi sırasıyla hangi değerlendirme türlerine benzetilebilir?', 'Biçimlendirici değerlendirme ve düzey belirleyici değerlendirme', ['Tanılayıcı değerlendirme ve biçimlendirici değerlendirme', 'Düzey belirleyici değerlendirme ve tanılayıcı değerlendirme', 'Bağıl değerlendirme ve tanılayıcı değerlendirme'], 'Robert Stake\'in ünlü metaforuna göre aşçının çorbayı tadıp düzeltmesi biçimlendirici, konuğun çorbayı tatması ise düzey belirleyici değerlendirmedir.'),
  ('Ünite sonlarında uygulanan biçimlendirici izleme testlerinde kapsam geçerliği sağlanırken düzey belirleyici dönem sonu sınavlarından farklı olarak hangi ilke esas alınır?', 'İşlenen dar kapsamlı ünitedeki tüm kritik davranışların yoklanması', ['Yıl boyunca işlenen tüm ünitelerden sadece en zor soruların seçilmesi', 'Öğrencilerin gelecekteki mesleki başarılarını tahmin edecek sorular sorulması', 'Grubun standart sapmasını en üst düzeye çıkaracak ayırt edici maddeler yazılması'], 'Biçimlendirici izleme testleri tek bir üniteye odaklandığından o ünitedeki tüm hedef davranışları yakından yoklar; dönem sonu sınavları ise geniş bir evrenden örneklem alır.'),
  ('Bir okulda uygulanan deneme sınavında öğrencilerin puanları Türkiye geneli yüzdelik dilimlerle raporlanırken, aynı sınavdaki yanlışlara göre her öğrenciye bireysel çalışma fasikülü verilmektedir. Bu uygulamada sırasıyla hangi yaklaşımlar bir arada kullanılmıştır?', 'Bağıl ölçütlü değerlendirme ve biçimlendirici yönlendirme', ['Mutlak ölçütlü değerlendirme ve tanılayıcı yerleştirme', 'Sertifikasyon amaçlı değerlendirme ve mutlak ölçütlü sıralama', 'Kazanım dayanaklı değer biçme ve norm dayanaklı not verme'], 'Yüzdelik dilim grubun içindeki yeri gösterdiğinden bağıl ölçüttür; yanlışlara göre eksik tamamlama fasikülü verilmesi ise biçimlendirici işlevdir.'),
  ('Bir öğretmenin dönem boyunca yaptığı biçimlendirici kısa sınavların (quizlerin) puanlarını doğrudan yıl sonu karne notuna yüksek ağırlıkla katması neden eleştirilir?', 'Öğrencilerin hata yapmaktan çekinmesine yol açarak öğrenme eksiklerini gizlemelerine neden olduğu için', ['Öğretmenin sınıf içi öğretim yöntemlerini gözden geçirmesini tamamen imkânsız hale getirdiği için', 'Çoktan seçmeli ve kısa yanıtlı soruların puanlama güvenirliğini istatistiksel olarak sıfırladığı için', 'Sınavların kapsam geçerliğini artırarak öğrencilerin sadece tek bir üniteye çalışmasını engellediği için'], 'Biçimlendirici değerlendirmeye not kaygısı yüklendiğinde öğrenciler hatalarını açıkça göstermekten kaçınır ve süreç öğrenmeyi destekleme işlevini yitirir.'),
  ('Standart sapmanın çok küçük ve aritmetik ortalamanın çok yüksek olduğu homojen bir sınıfta uygulanan sınav hakkında aşağıdakilerden hangisi söylenebilir?', 'Öğrencilerin büyük çoğunluğu benzer ve yüksek düzeyde başarı göstermiştir, grup içi farklılaşma azdır', ['Öğrenciler arasında çok keskin bilgi uçurumları vardır ve sınavın ayırt ediciliği en üst düzeydedir', 'Sınav soruları grubun hazırbulunuşluk düzeyinin çok üzerinde seçildiği için kimse başarılı olamamıştır', 'Ölçme aracına yüksek miktarda sabit hata karıştığı için tüm puanlar sıfır noktasına doğru yığılmıştır'], 'Küçük standart sapma puanların birbirine yakın (homojen) olduğunu, yüksek ortalama ise grubun genel başarısının yüksek olduğunu gösterir.'),
  ('Bir sınıftaki tüm öğrencilerin ham puanlarına 8 puan sabit ekleme yapıldığında (sabit hata), sınıfın istatistiksel göstergeleri ve bağıl değerlendirme sonuçları nasıl etkilenir?', 'Aritmetik ortalama 8 puan artar ancak standart sapma ve öğrencilerin birbirine göre başarı sırası değişmez', ['Standart sapma 8 katına çıkar ve sınıfın en başarısız öğrencileri ortalamanın üzerine yerleşir', 'Hem aritmetik ortalama hem de standart sapma sabit kalır ancak mutlak ölçütteki geçme oranı düşer', 'Mod ve medyan değerleri sabit kalırken grubun puan dağılımı sağa çarpık olmaktan çıkıp simetrikleşir'], 'Herkese aynı puan eklendiğinde ortalama aynı miktarda artar fakat puanlar arasındaki farklar değişmediği için standart sapma ve bağıl sıralama aynı kalır.'),
  ('Tam öğrenme modelini (Bloom) benimseyen bir öğretmenin ölçme-değerlendirme sürecinde izlemesi gereken temel ilke aşağıdakilerden hangisidir?', 'Ünite sonlarında biçimlendirici izleme testleri uygulayıp mutlak ölçüte (%70 ve üzeri) ulaşamayanlara tamamlayıcı öğretim sunmak', ['Dönem boyunca hiç ara değerlendirme yapmadan final sınavında çan eğrisi uygulayarak öğrencilerin yarısını elemek', 'Öğrencilerin hazırbulunuşluk eksiklerini dikkate almadan tüm sınıfa tek tip anlatım yöntemiyle hızlandırılmış ders işlemek', 'İzleme testlerinden alınan puanları sınıf ortalamasıyla karşılaştırarak en düşük puanlı öğrencileri alt seviye sınıflarına göndermek'], 'Tam öğrenme modelinde ünite başında tanılayıcı, ünite sonunda mutlak ölçütlü biçimlendirici izleme testleri uygulanır ve tam öğrenme sağlanmadan yeni üniteye geçilmez.'),
  ('Ülke genelinde uygulanan merkezi bir yerleştirme sınavında (örneğin LGS veya YKS) standart puan ve yüzdelik dilim hesaplanmasının temel gerekçesi nedir?', 'Farklı testlerin ortalama ve standart sapmalarını eşitleyerek adayların grup içindeki göreceli konumlarını adilce karşılaştırmak', ['Her adayın müfredattaki kazanımların yüzde kaçına tam olarak ulaştığını grup başarısından bağımsız biçimde belgelemek', 'Sınavda sorulan tüm maddelerin güçlük indekslerini sıfırlayarak her adayın tam puan almasını garanti altına almak', 'Öğrencilerin lise veya ortaokul boyunca yaşadıkları kavram yanılgılarını tespit edip telafi dersleri planlamak'], 'Farklı alt testlerin güçlük ve dağılımları farklı olduğundan, standart puanlar (Z ve T puanları) ile adayların grup içindeki bağıl konumları karşılaştırılabilir hale getirilir.'),
  ('Bir öğretmen ünite başında tanılayıcı bir ön test, ünite sonunda ise aynı kapsamda düzey belirleyici bir son test uygulamıştır. Ön test ortalaması 25, son test ortalaması 82 çıktığına göre en tutarlı yorum hangisidir?', 'Yürütülen öğretim etkinlikleri öğrencilerin hedef kazanımlara ulaşmasında yüksek düzeyde etkili olmuştur', ['Ön testteki sorular çok zor, son testteki sorular ise kapsam dışı ve geçersiz maddelerden seçilmiştir', 'Öğrenciler dönem başında konuyu zaten tam olarak bildikleri için öğretim süreci zaman kaybına yol açmıştır', 'Sınıfta bağıl değerlendirme yapıldığı için son testte öğrencilerin büyük bölümü dersten başarısız sayılmıştır'], 'Eşdeğer kapsamlı ön test ve son test arasındaki belirgin puan artışı (erişi), öğretim sürecinin etkililiğini gösteren güçlü bir kanıttır.'),
  ('Aşağıdaki durumlardan hangisinde "mutlak ölçüt" yerine "bağıl ölçüt" kullanılması ölçme ve değerlendirme ilkeleri açısından daha doğru bir tercihtir?', 'Bursluluk sınavında bütçe olanakları doğrultusunda en yüksek puanlı ilk 500 öğrenciye burs tahsis edilmesinde', ['İlk yardım kursunda kalp masajı uygulama yeterliği kazanan kursiyerlere resmi ilk yardımcı belgesi verilmesinde', 'İlkokul üçüncü sınıf öğrencilerinin çarpım tablosundaki temel işlemleri kavrayıp kavramadığının kontrol edilmesinde', 'Uçuş akademisindeki pilot adaylarının acil iniş prosedürlerini hatasız uygulayabilme becerilerinin onaylanmasında'], 'Kaynak veya kontenjan sınırlılığı bulunan burs, iş başvurusu gibi seçme durumlarında en üst sıradaki adayları belirlemek için bağıl ölçüt kullanılır.'),
  ('"Güvenirlik, geçerlik için gerekli bir ön şarttır ancak tek başına yeterli değildir." ilkesinden hareketle aşağıdaki çıkarımlardan hangisine kesin olarak ulaşılır?', 'Geçerliği yüksek olduğu kanıtlanmış bir ölçme aracının güvenirliği de zorunlu olarak yüksektir', ['Güvenirliği çok yüksek hesaplanan her test, uygulandığı her amaç ve grup için kesinlikle geçerlidir', 'Tesadüfi hatalarla dolu güvenilmez bir testin kapsam ve yordama geçerliği en üst düzeyde çıkabilir', 'Sabit hatalar güvenirliği tamamen sıfırlarken geçerlik katsayısını hiçbir biçimde etkilemez'], 'Bir test amacına uygun ve doğru ölçüm yapıyorsa (geçerliyse) zaten tutarlı olmak zorundadır; dolayısıyla geçerliği yüksek olan aracın güvenirliği de yüksektir.'),
  ('Öğrenme eksiklerini belirlemek amacıyla yapılan biçimlendirici (izleme) bir testte birçok maddenin güçlük indeksinin 0,85 civarında çıkması ve ayırt ediciliğin düşük görünmesi nasıl yorumlanmalıdır?', 'Sınıfın büyük çoğunluğu hedeflenen kazanımları öğrendiği için beklenen ve istenen bir durumdur', ['Test tamamen hatalı hazırlandığı için tüm sorular iptal edilip çok zor sorularla yeniden sınav yapılmalıdır', 'Öğrencilerin kopya çektiği kesinleştiğinden disiplin soruşturması başlatılıp notları sıfırlanmalıdır', 'Eğitim sürecinin tamamen başarısız olduğu anlaşıldığından tüm konular baştan sona tekrar anlatılmalıdır'], 'Tam öğrenme ve biçimlendirici izleme testlerinde amaç öğrencileri elemek değil herkesin öğrenmesini sağlamaktır; çoğu öğrencinin doğru yanıtlaması (pj\'nin yüksek olması) öğretimin başarılı olduğunu gösterir.'),
  ('Bir üniversitede "Çan eğrisi sisteminde sınıf ortalaması 35\'in altına düşerse bağıl değerlendirme iptal edilir ve geçme notu doğrudan 50 olarak uygulanır." kuralı getirilmiştir. Bu hibrit kuralın temel amacı nedir?', 'Genel başarının çok düşük olduğu sınıflarda yetersiz bilgi düzeyindeki öğrencilerin bağıl ölçüt sayesinde kolayca ders geçmesini önlemek', ['Sınıf ortalaması çok yükseldiğinde başarılı öğrencilerin tamamını cezalandırarak dersi tekrar almalarını zorunlu kılmak', 'Öğretim elemanlarının dönem içinde biçimlendirici ödev ve kısa sınav yapma yetkilerini tamamen ellerinden almak', 'Sınav sorularının kapsam geçerliğini düşürerek sadece tek bir üniteden soru sorulmasını yasal güvenceye kavuşturmak'], 'Bağıl değerlendirmede grup çok başarısızsa çok düşük puanlarla (örneğin 30 ile) ders geçilebilir; alt sınır getirilerek asgari yeterlik (mutlak baraj) güvenceye alınır.'),
  ('Çağdaş eğitimde değerlendirmenin "öğrenme olarak değerlendirme" (assessment as learning) boyutu dikkate alındığında öğrenciden beklenen temel rol aşağıdakilerden hangisidir?', 'Kendi öğrenme sürecini üstbilişsel olarak izleyen, ölçütlere göre öz değerlendirme yapıp stratejisini düzenleyen aktif özne olmak', ['Öğretmenin verdiği puanları hiçbir sorgulama yapmadan kabullenip sadece ezberlenecek ders notlarına odaklanmak', 'Sınıf arkadaşlarının sınav puanlarını takip ederek çan eğrisinde üst dilime çıkabilmek için bilgi paylaşımından kaçınmak', 'Değerlendirme sorumluluğunu tamamen dış denetçilere ve merkezi test merkezlerine bırakarak pasif biçimde sonuç beklemek'], '"Öğrenme olarak değerlendirme", öğrencinin üstbilişsel (metabilişsel) farkındalıkla kendi öğrenmesini izlediği ve öz düzenleme yaptığı yaklaşımdır.'),
  ('Puan dağılımının sola çarpık (negatif kayışlı) olduğu bir sınıf sınavı hakkında aşağıdaki istatistiksel ve pedagojik yorumlardan hangisi kesinlikle doğrudur?', 'Puanlar yüksek değerlerde yığılmıştır; sınav gruba kolay gelmiş veya öğrencilerin çoğunluğu yüksek başarı göstermiştir', ['Puanlar düşük değerlerde toplanmıştır; sınav soruları öğrencilerin hazırbulunuşluk düzeyinin çok üzerinde kalmıştır', 'Aritmetik ortalama, ortanca (medyan) ve tepe değer (mod) birbirine tam eşit olup kusursuz bir simetri oluşmuştur', 'Sınıftaki tüm öğrenciler sınavdan sıfır puan aldığı için bağıl ölçüt uygulanması matematiksel olarak zorunlu hale gelmiştir'], 'Sola çarpık dağılımda kuyruk sol (düşük puan) taraftadır ve yığılma sağda (yüksek puanlarda) gerçekleşir; bu durum grubun başarılı olduğunu veya testin kolay geldiğini gösterir.'),
  ('Eğitimde ölçme ve değerlendirmenin etik ve pedagojik ilkeleri bütüncül olarak düşünüldüğünde aşağıdaki uygulamalardan hangisi "adil ve geçerli değerlendirme" anlayışına en uygun düşer?', 'Öğrencileri farklı bilişsel düzeyleri yoklayan çeşitli ölçme araçlarıyla süreç ve sonuç boyutunda değerlendirip ölçütleri baştan şeffafça paylaşmak', ['Tüm öğrencilerin bireysel farklılıklarını yok sayarak yıl boyunca sadece tek bir çoktan seçmeli sınavla kesin başarı kararı vermek', 'Sınav sorularını işlenmeyen ünitelerden seçerek sadece özel ders alan öğrencilerin çözebileceği ayırt ediciliği yüksek bir eleme yapmak', 'Disiplin cezası gerektiren sınıf içi istenmeyen davranışları öğrencinin akademik yazılı sınav puanından kesinti yaparak cezalandırmak'], 'Geçerli ve adil değerlendirme; çoklu ölçme araçları kullanmayı, şeffaf ölçütler sunmayı ve akademik başarıya davranış/disiplin cezalarını karıştırmamayı gerektirir.'),
  ('Dereceli puanlama anahtarlarının (rubriklerin) performans görevi verilmeden önce öğrencilerle paylaşılmasının ölçme ve öğrenme sürecine en kritik katkısı nedir?', 'Beklentileri şeffaflaştırarak öğrencinin kendi çalışmasını ölçütlere göre yönlendirmesini (öz düzenleme) sağlaması', ['Öğrencilerin sadece en düşük puan dilimindeki şartları yerine getirerek çalışmayı erken bırakmasına yol açması', 'Öğretmenin ödevleri okuma ve geri bildirim verme sorumluluğunu tamamen ortadan kaldırması', 'Sınıftaki tüm projelerin içerik ve biçim açısından birbirinin birebir kopyası haline gelmesini zorunlu kılması'], 'Rubriğin önceden paylaşılması belirsizliği giderir, beklentileri netleştirir ve öğrencinin hedef kaliteye ulaşmak için öz denetim yapmasını destekler.'),
  ('İyi yapılandırılmış bir analitik rubrikteki performans düzeyi tanımlayıcıları incelendiğinde aşağıdaki kusurlardan hangisinin bulunmaması gerekir?', '"Oldukça iyi, fena değil, biraz eksik" gibi puanlayıcıdan puanlayıcıya değişen muğlak ve öznel ifadeler', ['Her performans basamağını bir alt ve bir üst basamaktan net biçimde ayıran gözlenebilir ölçütler', 'Öğrencinin ulaşması hedeflenen kazanımlarla doğrudan örtüşen açık ve anlaşılır beceri boyutları', 'Yaratıcılığı kısıtlamadan ürünün niteliğine odaklanan dengeli ve kapsayıcı değerlendirme basamakları'], 'Rubrik tanımlayıcılarında "oldukça, biraz, güzel" gibi muğlak sıfatlar kullanmak puanlayıcılar arası tutarlılığı (güvenirliği) düşürür; somut betimlemeler şarttır.'),
  ('Portfolyo değerlendirmesini sıradan bir "ödev biriktirme klasörü" olmaktan çıkaran en temel pedagojik bileşen aşağıdakilerden hangisidir?', 'Öğrencinin seçtiği ürünlere ilişkin neden o çalışmayı seçtiğini ve ne öğrendiğini açıkladığı "yansıtma (refleksiyon) yazıları"', ['Dosyanın dış kapağının pahalı ve renkli kırtasiye malzemeleriyle süslenerek görsel açıdan gösterişli hale getirilmesi', 'Sınıftaki tüm öğrencilerin dosyalarına öğretmenin hiçbir inceleme yapmadan standart olarak yüz tam puan vermesi', 'Yıl boyunca dağıtılan tüm çoktan seçmeli yaprak testlerin fotokopilerinin eksiksiz biçimde klasöre delinerek takılması'], 'Portfolyonun kalbi öğrencinin kendi gelişimi üzerine düşündüğü, güçlü ve gelişime açık yönlerini sorguladığı öz yansıtma (reflection) metinleridir.'),
  ('Araştırmalar, öğrencinin çalışmasına değil doğrudan "benliğine/kişiliğine" yöneltilen övgü veya yergi içeren geri bildirimlerin (örneğin "Çok zekisin" veya "Yeteneksizsin") öğrenme üzerinde nasıl bir etki yarattığını göstermektedir?', 'Zorlu görevlerde hata yapma korkusu yaratarak çaba göstermekten kaçınmaya (sabit zihniyet) yol açtığından öğrenmeye katkısı en düşüktür', ['Öğrencinin üstbilişsel strateji kullanımını en üst düzeye çıkararak karmaşık problemleri anında çözmesini sağlar', 'Analitik rubrik kullanımına duyulan ihtiyacı tamamen ortadan kaldırarak puanlama güvenirliğini maksimuma ulaştırır', 'Öğrencinin eksik kalan konu başlıklarını kendi kendine teşhis etmesi için gerekli tüm teknik ipuçlarını eksiksiz sunar'], 'Benlik/kişilik odaklı (ego-involving) dönütler görev stratejisi hakkında hiçbir bilgi içermez ve öğrencide hata yapmaktan kaçınma eğilimi yaratır.'),
  ('Bir proje çalışmasında grup ürününe ortak puan verildiğinde bazı öğrencilerin çaba harcamadan arkadaşlarının sırtından geçinmesi ("sosyal kaytarma") sorununu çözmek için akran ve öz değerlendirme nasıl kullanılmalıdır?', 'Bireysel katkı ve sorumluluk ölçütleri içeren akran/öz değerlendirme formları ile öğretmen gözlemlerini birleştirerek bireysel süreci izlemek', ['Grup projelerini müfredattan tamamen kaldırarak öğrencilerin hayatları boyunca sadece bireysel çoktan seçmeli test çözmelerini sağlamak', 'Grubun içinden rastgele kura ile seçilen tek bir öğrencinin yaptığı işi tüm grubun ortak puanı olarak tescil etmek', 'Sosyal kaytarma yaşandığında projeyi eksiksiz yapan çalışkan öğrencilerin puanlarını keserek tüm grubu sıfırla cezalandırmak'], 'Grup çalışmalarında bireysel hesap verebilirliği sağlamak için öğretmen gözleminin yanında yapılandırılmış akran ve öz değerlendirme kanıtları kullanılır.'),
  ('"İleriye dönük geri bildirim" (feed-forward) kavramını sınıfında etkili biçimde uygulayan bir öğretmenin aşağıdaki davranışlardan hangisini sergilemesi beklenir?', 'Öğrencinin sadece geçmiş ödevdeki hatasını işaretlemekle kalmayıp, bir sonraki taslakta çalışmasını nasıl geliştireceğine dair somut strateji sunması ve revizyon fırsatı tanıması', ['Ödev teslim edildikten sonra konuyu tamamen kapatıp hiçbir düzeltme hakkı tanımadan doğrudan yeni ünitenin sınavına geçmesi', 'Öğrencinin bir önceki yılda aldığı karne notlarını sınıfta yüksek sesle okuyarak geçmişteki başarısızlıklarını hatırlatması', 'Sadece doğru yanıtların altını kırmızı kalemle çizip yanlış yapılan kısımlara büyük soru işaretleri koyarak kâğıdı iade etmesi'], 'Feed-forward (ileriye dönük bildirim), geri bildirimin bir sonraki adımda veya revizyonda eyleme dönüştürülmesini ve gelişim için kullanılmasını sağlar.'),
  ('Bir öğretmenin analitik rubrik hazırlarken "Sunum slaydı tam 12 sayfa olmalı, kapakta mavi renk kullanılmalı ve başlık 24 punto yazılmalı" gibi maddeleri en yüksek ağırlıklı ölçütler olarak belirlemesi neden hatalıdır?', 'Hedeflenen asıl bilişsel/iletişimsel beceri (içerik kalitesi ve sunum yetkinliği) yerine yüzeysel biçimsel özelliklere odaklanarak yapı ve kapsam geçerliğini zedelediği için', ['Sayısal olarak ifade edilen sayfa ve punto kurallarının puanlayıcılar tarafından kontrol edilmesinin imkânsız olması nedeniyle güvenirliği düşürdüğü için', 'Öğrencilerin bilgisayarda sunum hazırlarken farklı yazı tiplerini denemesini tamamen yasaklayarak telif haklarını ihlal ettiği için', 'Bütüncül rubriklerde bulunması gereken sayfa sınırı kurallarını yanlışlıkla analitik rubrik şablonuna aktardığı için'], 'Rubrik ölçütleri şekilsel/yüzeysel ayrıntılara boğulduğunda öğrenci öğrenmeye değil şekil şartlarına odaklanır; bu da değerlendirmenin geçerliğini bozar.'),
  ('Portfolyoların geniş ölçekli (ulusal düzeyde seçme ve yerleştirme gibi) düzey belirleyici kararlarda tek başına kullanılmasının önündeki en önemli ölçme bilimi engeli nedir?', 'İçeriklerin bireyselliği nedeniyle puanlamanın çok zaman alması ve farklı puanlayıcılar arasında standartlaştırma/güvenirlik sağlamanın güç olması', ['Portfolyoların öğrencilerin yaratıcılığını, problem çözme becerisini ve süreç içindeki gelişimini hiçbir biçimde yansıtamaması', 'Öğrencilerin gerçek yaşamla ilişkili özgün ürünler ortaya koymasına izin vermeyen katı ve ezberci bir yapıya sahip olması', 'Portfolyo hazırlama sürecinin öğretmen ile öğrenci arasındaki biçimlendirici iletişimi tamamen koparması'], 'Portfolyolar geçerliği ve derinliği çok yüksek araçlardır; ancak standardizasyon zorluğu, zaman maliyeti ve puanlayıcı güvenirliği sorunları nedeniyle geniş ölçekli sıralama sınavlarında kullanışlılığı düşüktür.'),
  ('Bir öğretmen rubrik eğitimi verirken geçmiş yıllardan isimleri gizlenmiş "zayıf, orta ve mükemmel" nitelikte üç örnek öğrenci çalışmasını (çıpa/örneklem ürünleri) sınıfla birlikte rubriğe göre inceleyip tartışmaktadır. Bu uygulamanın en güçlü pedagojik etkisi nedir?', 'Soyut değerlendirme ölçütlerini somut örnekler üzerinde görünür kılarak öğrencilerin "nitelikli iş" algısını kalibre etmesi', ['Öğrencilerin kendi özgün fikirlerini bir kenara bırakıp geçmiş yıldaki örnek ödevi kelimesi kelimesine kopyalamasını meşrulaştırması', 'Zayıf örnek çalışmayı hazırlayan eski öğrencinin kimliğinin tahmin edilerek okul içinde alay konusu yapılmasına yol açması', 'Öğretmenin yeni dönemde rubrik hazırlama zahmetinden kurtularak tüm ödevleri otomatik olarak geçersiz sayması'], 'Çıpa (anchor/exemplar) ürünlerin incelenmesi, rubrikteki yazılı tanımların pratikte neye karşılık geldiğini somutlaştırarak öz ve akran değerlendirme kalitesini yükseltir.'),
  ('Geri bildirimin niteliği üzerine çalışan çağdaş kuramcılar (örneğin Boud ve Carless), geri bildirimi öğretmenden öğrenciye tek yönlü bir "bilgi aktarımı" olmaktan çıkarıp "diyalojik bir süreç ve geri bildirim okuryazarlığı" olarak tanımlamaktadır. Buna göre "geri bildirim okuryazarı" bir öğrenci ne yapar?', 'Aldığı dönütleri anlamlandırır, anlamadığı noktaları sorar, duygusal savunmaya geçmeden değerlendirir ve sonraki çalışmalarında somut eyleme dönüştürür', ['Öğretmenin yazdığı yorumları ezberleyerek bir sonraki çoktan seçmeli sınavda tanım sorusu olarak çıkmasını bekler', 'Yalnızca olumlu övgü cümlelerini okuyup eleştirel gelişim önerilerinin yer aldığı sayfaları okumadan çöpe atar', 'Her cümlesini öğretmene onaylatmadan kendi başına hiçbir paragraf yazamayacak derecede dışa bağımlı hale gelir'], 'Geri bildirim ancak öğrenci tarafından anlaşılıp içselleştirildiğinde ve bir sonraki performansta kullanıldığında (eyleme geçtiğinde) gerçek amacına ulaşır.'),
  ('Performans değerlendirme ve rubrik kullanımında sıkça karşılaşılan "hale (halo) etkisi" yanlılığı aşağıdakilerden hangisinde doğru örneklenmiştir?', 'Öğretmenin, derslerde çok saygılı ve genel akademik başarısı yüksek olan bir öğrencinin zayıf hazırladığı proje ödevine de rubrikteki kusurları görmezden gelerek yüksek puan vermesi', ['Öğretmenin okuduğu tüm proje ödevlerine içerik kalitesine bakmaksızın orta basamak olan 3 puanı verip geçmesi', 'Sabah okuduğu ilk ödevlere çok bol puan veren öğretmenin akşam yorulunca son ödevlere çok kıt puan vermesi', 'Rubrikteki tüm ölçütlerin öğrencilerin öğrenme hedefleriyle birebir uyumlu ve açık ifadelerle tanımlanmış olması'], 'Bireyin genel olumlu izleniminin (veya bir alandaki başarısının) diğer spesifik özelliklerinin puanlanmasını olumlu yönde çarpıtmasına hale (halo) etkisi denir.'),
  ('Biçimlendirici geri bildirimin "bilişsel yük" açısından değerlendirilmesi gerektiğinde, bir öğrencinin kompozisyonundaki 35 farklı dil bilgisi, içerik ve üslup hatasının tamamının tek seferde kırmızı kalemle işaretlenip düzeltilmesi neden etkisiz kalabilir?', 'Aşırı bilgi yüklemesi öğrencide bunalmışlık ve çaresizlik hissi yaratarak en kritik gelişim alanlarına odaklanmasını engellediği için', ['Kırmızı kalem mürekkebinin kâğıt üzerindeki okunaklılığı teknik olarak tamamen ortadan kaldırdığı için', 'Öğrencinin bir günde tüm hatalarını kusursuzca öğrenip bir daha ödev yapmaya ihtiyaç duymamasına neden olduğu için', 'Türkçe derslerinde yazım ve noktalama kurallarının hiçbir koşulda değerlendirme ölçütü olamayacağı kabul edildiği için'], 'Etkili geri bildirim seçici ve önceliklendirilmiş olmalıdır; tüm hatalara aynı anda yüklenmek bilişsel yükü aşar ve öğrencinin motivasyonunu kırar.'),
  ('Bir okulda "Biçimlendirici Değerlendirme Kültürünü Güçlendirme" projesi kapsamında öğretmenlerin geri bildirim pratiğini geliştirmek isteyen bir eğitim uzmanının aşağıdaki önerilerden hangisini sunması en doğrudur?', 'Geri bildirimi yalnızca ödev bittiğinde verilen bir yargı olmaktan çıkarıp, öğrencinin revizyon yaparak gelişimini kanıtlayabileceği döngüsel bir süreç olarak tasarlamak', ['Öğretmenlerin zaman kazanması için tüm öğrenci ödevlerine "Eksiklerini tamamla, daha dikkatli ol." şeklinde tek tip kaşe basmalarını sağlamak', 'Geri bildirim toplantılarında öğrencilerin puanlarını okul panosunda en yüksekten en düşüğe doğru tam isim listesiyle ilan etmek', 'Biçimlendirici süreçte verilen her ipucu karşılığında öğrencinin dönem sonu yazılı puanından beşer puan kesinti uygulamak'], 'Geri bildirim döngüsü ancak öğrenci dönütü alıp çalışmasını revize etme (iyileştirme) şansı bulduğunda öğrenmeyi somut biçimde dönüştürür.'),
  ('Bir öğretmenin performans görevini değerlendirirken hazırladığı analitik rubrikte "İçerik Doğruluğu" boyutuna maksimum 40 puan, "Kaynakça Kullanımı"na 20 puan, "Görsel Düzen"e 10 puan ve "Sözlü Sunum"a 30 puan tanımlaması hangi tasarım ilkesini gösterir?', 'Ölçütlerin hedef kazanımlardaki önem derecesine göre farklı ağırlıklarla puanlamaya katılması (ağırlıklandırma) ilkesini', ['Tüm alt becerilerin eşit puana sahip olması gerektiğini savunan standart rubrik simetrisi kuralının ihlalini', 'Puanlayıcılar arası güvenirliği düşürmek için kasıtlı olarak karmaşık katsayılar seçilmesi hatasını', 'Bütüncül rubrik ile kontrol listesinin birbirine karıştırılmasından doğan yapısal ölçme kusurunu'], 'Analitik rubriklerde her boyutun kazanımdaki kritikliği aynı olmayabilir; daha önemli boyutlara (içerik doğruluğu gibi) daha yüksek ağırlık verilmesi kapsam ve yapı geçerliğini güçlendirir.'),
  ('Portfolyo değerlendirmesinin puanlanmasında hem süreçteki gelişimi hem de ürünlerin kalitesini adil biçimde yansıtmak isteyen bir öğretmen nasıl bir değerlendirme stratejisi kurgulamalıdır?', 'Dosya düzeni, ürünlerin niteliği, zaman içindeki gelişim (erişi) ve öz yansıtma derinliğini alt boyutlar olarak içeren şeffaf bir portfolyo rubriği kullanmalıdır', ['Dosyanın ağırlığını ve sayfa sayısını ölçerek en kalın dosyayı getiren öğrenciye en yüksek puanı vermelidir', 'Yalnızca dosyanın içindeki ilk hafta çalışmasını puanlayıp sonraki aylarda yapılan tüm düzeltmeleri yok saymalıdır', 'Sınıftaki tüm portfolyoları çan eğrisine sokarak dosyası eksiksiz olan öğrencilerin bile yarısını başarısız ilan etmelidir'], 'Geçerli bir portfolyo değerlendirmesi; seçilen kanıtların niteliğini, başlangıçtan sona kaydedilen gelişimi ve öğrencinin yansıtıcı düşüncesini bütüncül bir analitik rubrikle ele alır.'),
  ('Öz referanslı (bireyin kendi geçmişiyle kıyaslandığı) geri bildirim biçimlendirici süreçte motivasyonu çok olumlu etkilerken, mezuniyet ve yeterlik belgesi verme (summatif) aşamasında neden tek başına yeterli olamaz?', 'Başlangıç noktası çok düşük olan bir öğrenci büyük ilerleme kaydetmiş olsa bile mesleki/akademik asgari yeterlik standardına (mutlak ölçüte) henüz ulaşamamış olabileceği için', ['Bireyin kendi gelişimini izlemesinin eğitim bilimleri açısından tamamen geçersiz ve güvenilmez kabul edilmesi nedeniyle', 'Öz referanslı değerlendirmenin her zaman öğrencilerin birbirleriyle kıyasıya rekabet etmesine ve kopya çekmesine yol açtığı için', 'Öğretmenlerin öğrencilerin geçmiş çalışmalarını portfolyo dosyalarında saklamasının teknik olarak imkânsız olmasından dolayı'], 'Bireysel ilerleme süreç içinde çok değerlidir; ancak diploma veya sertifika verirken bireyin dışsal hedef standartlara (mutlak yeterliğe) ulaşıp ulaşmadığı da doğrulanmalıdır.'),
  ('Bir öğretmenin hazırladığı rubrikte "4 Puan: Konuyu eksiksiz açıklar ve 3 örnek verir", "3 Puan: Konuyu açıklar ve 2 örnek verir", "2 Puan: Konuyu kısmen açıklar ve 1 örnek verir" şeklinde yalnızca örnek sayısına dayalı basamaklar kurgulaması hangi açıdan eleştirilebilir?', 'Verilen örneklerin niteliğini, özgünlüğünü ve kavramla uyumunu göz ardı edip kaliteyi salt niceliksel (sayısal) saymaya indirgediği için', ['Öğrencilerin üçten fazla örnek bilmesini matematiksel olarak yasaklayıp yaratıcılığı ödüllendirdiği için', 'Bütüncül rubriklerde yer alması zorunlu olan yüzdelik dilim hesaplarını içermediği için', 'Sayısal ifadelerin farklı puanlayıcılar tarafından anlaşılmasını tamamen imkânsız hale getirdiği için'], 'İyi bir rubrik sadece "kaç tane" örnek verildiğini (niceliği) değil, örneklerin ne kadar doğru, derinlikli ve özgün olduğunu (niteliği) betimlemelidir.'),
  ('Akran değerlendirmesinin düzey belirleyici (not verme amaçlı) kullanılması ile biçimlendirici (yorum ve geliştirme amaçlı) kullanılması karşılaştırıldığında araştırmaların ortaya koyduğu temel bulgu nedir?', 'Akran değerlendirmesi not verme baskısından arındırılıp biçimlendirici geri bildirim amacıyla kullanıldığında hem dürüstlük hem de öğrenme kazanımı çok daha yüksek olmaktadır', ['Akranların verdiği puanlar karne notunu doğrudan belirlediğinde öğrenciler arasında hiçbir duygusal gerilim veya yanlılık yaşanmamaktadır', 'Biçimlendirici amaçla yapılan akran değerlendirmeleri öğrencilerin okuma ve yazma becerilerini geriletmektedir', 'Akran değerlendirmesi yalnızca öğrencilerin birbirlerini okuldan elemek üzere yarıştıkları sınavlarda geçerli sonuçlar üretmektedir'], 'Akran puanları yüksek riskli notlara dönüştüğünde arkadaşlık kaygısı veya rekabet devreye girerek geçerliği bozar; biçimlendirici kullanımda ise pedagojik verim zirveye çıkar.'),
  ('Tanılayıcı, biçimlendirici ve düzey belirleyici değerlendirme ile rubrik, portfolyo, akran değerlendirmesi ve geri bildirim ilkeleri bütüncül bir eğitim sisteminde nasıl konumlandırılmalıdır?', 'Öğretim başında tanılayıcı, süreç boyunca rubrik/portfolyo/akran dönütüyle desteklenen biçimlendirici ve süreç sonunda amaca uygun ölçütlü düzey belirleyici yaklaşımlar birbirini tamamlayacak şekilde bütünleştirilmelidir', ['Okullarda kâğıt-kalem sınavları tamamen yasaklanmalı ve mezuniyet kararları yalnızca öğrencilerin kendi kendilerine verdikleri öz değerlendirme puanlarıyla alınmalıdır', 'Biçimlendirici değerlendirme ve geri bildirim zaman kaybı yarattığı için terk edilmeli, eğitim yılı boyunca sadece tek bir bağıl ölçütlü merkezi sınav uygulanmalıdır', 'Her derste her gün hem portfolyo hem analitik rubrik hem de yüz soruluk çoktan seçmeli test aynı anda uygulanarak öğrenciler aralıksız sınav baskısı altında tutulmalıdır'], 'Nitelikli bir ölçme-değerlendirme sistemi; tanılayıcı, biçimlendirici ve düzey belirleyici işlevleri amaca uygun ölçütler ve tamamlayıcı araçlarla dengeli biçimde uyumlaştırır.'),
];
